import type { Message } from '@/types';
import { memo, useMemo } from 'react';
import { Undo2 } from 'lucide-react';
import { useSessionStore } from '@/stores/sessionStore';
import { MarkdownRenderer } from './MarkdownRenderer';
import { ThinkingBlock } from './ThinkingBlock';
import { ThinkingGroup } from './ThinkingGroup';
import { ToolGroup } from './ToolGroup';
import { NonBodyGroup } from './NonBodyGroup';
import type { GroupDisplayItem } from '@/utils/messageIdentity';
import { getMessageIdentity } from '@/utils/messageIdentity';
import { isValidMessageTs } from '@/utils/messageTimestamp';
import { getMessageSourceTag, type MessageSourceTag } from './messageFilter';
import { MessageTimestamp } from './MessageTimestamp';
import { useAppSettingsStore } from '@/stores/appSettingsStore';
export { formatMessageTs } from '@/utils/messageTimestamp';

export type GroupedItem = Message | GroupDisplayItem;
type PrevRole = Message['role'] | 'tool' | null;

/**
 * Raw view body: the message text is a plain React text node inside a
 * `white-space: pre-wrap` block. Newlines, runs of spaces, Markdown markers,
 * code fences and literal HTML are preserved verbatim — nothing is parsed,
 * highlighted or injected as markup. Copying the block yields the original
 * text, including its line breaks. Long unbreakable tokens wrap with
 * `overflow-wrap: anywhere` instead of widening the virtualized row.
 */
function RawMessageText({ content, className = '' }: { content: string; className?: string }) {
  return (
    <div
      data-raw-message-text=""
      className={`whitespace-pre-wrap [overflow-wrap:anywhere] ${className}`.trim()}
    >
      {content}
    </div>
  );
}

/** Role used for spacing decisions. Groups use the role of their member blocks. */
export function getItemRole(item: GroupedItem): PrevRole {
  if ('type' in item) {
    if (item.type === 'non_body_group') return item.items[item.items.length - 1]?.role ?? 'tool';
    return item.type === 'tool_group' ? 'tool' : 'thinking';
  }
  return (item as Message).role;
}

/** Kimi-style variant-aware top spacing.
 *  Mirrors kimi-cli's virtualized-message-list spacing rules:
 *  user pt-4, assistant-after-user pt-2, consecutive-assistant pt-1,
 *  tool pt-1.5, thinking pt-1.
 *
 * Padding is intentional here. A margin inside a measured virtual row can
 * collapse outside the row, making its cached height smaller than its painted
 * content and allowing the next row to overlap it. */
function marginTopClass(role: PrevRole, prevRole: PrevRole): string {
  if (!prevRole) return '';
  if (role === 'user') return 'pt-4';
  if (role === 'assistant') return prevRole === 'user' ? 'pt-2' : 'pt-1';
  if (role === 'tool') return 'pt-1.5';
  if (role === 'thinking') return 'pt-1';
  return 'pt-1';
}

interface MessageBubbleProps {
  message: Message;
  prevRole?: PrevRole;
}

/** User-facing copy for the durable source tags (classification: messageFilter). */
const SOURCE_TAG_LABELS: Record<MessageSourceTag, string> = {
  'ta-report': 'TA report',
  'ma-assign': 'MA assign',
  system: 'System',
};

export const MessageBubble = memo(function MessageBubble({ message, prevRole = null }: MessageBubbleProps) {
  const role = message.role;
  const mt = marginTopClass(role, prevRole);
  // Raw view keeps the TUI rows and role bars but swaps the rendered Markdown
  // body for the message's original text. Read straight from the store so a
  // mode switch re-renders only this body — no prop drilling, no new context.
  const rawViewEnabled = useAppSettingsStore((s) => s.chatViewStyle === 'raw');
  const attachmentIds = useMemo(
    () => message.parts?.flatMap((part) => part.type === 'attachment' ? [part.attachmentId] : []),
    [message.parts],
  );
  const sourceTag = getMessageSourceTag(message);
  const sourceBadge = sourceTag ? (
    <span
      className="worker-report-label"
      data-source-tag={sourceTag}
      aria-label={SOURCE_TAG_LABELS[sourceTag]}
    >
      {SOURCE_TAG_LABELS[sourceTag]}
    </span>
  ) : null;
  const openRewind = useSessionStore((s) => s.openRewind);
  const currentSession = useSessionStore((s) => s.sessions.find((session) => session.id === s.currentSessionId));
  const sessionBusy = ['running', 'queued'].includes(currentSession?.workerStatus ?? '');
  // Rewind anchors are user-role only (worker report messages included, they
  // land in history as role=user). Busy sessions grey the button out.
  const showRewind = role === 'user' && !message.streaming;
  const actions = showRewind ? (
    <div className="mt-1 flex items-center gap-2">
      <button type="button" onClick={() => openRewind(message)} disabled={sessionBusy}
        className="inline-flex items-center gap-1 text-xs text-text-tertiary hover:text-text-primary disabled:opacity-50"
        title={sessionBusy ? '任务运行中，无法撤回' : '从此消息撤回并分叉'}>
        <Undo2 size={13} /> 撤回
      </button>
    </div>
  ) : null;

  // Thinking blocks get their own component
  if (role === 'thinking') {
    return (
      <div className={`${mt} px-3 sm:px-6 lg:px-8`}>
        <ThinkingBlock message={message} />
      </div>
    );
  }

  // Tool blocks are handled by ToolGroup — they shouldn't appear standalone
  if (role === 'tool') {
    return null;
  }

  // System messages
  if (role === 'system') {
    return (
      <div className={`system-message flex justify-center py-2 ${mt}`}>
        <div className="inline-flex min-w-0 flex-col items-start">
          {sourceBadge}
          <span className="msg system text-xs text-text-tertiary bg-bg-tertiary rounded px-3 py-1">
            {message.content}
          </span>
        </div>
      </div>
    );
  }

  // TUI-style message rows use flex alignment so the virtualized row can keep
  // its full width without changing the measured wrapper's layout.
  if (role === 'user') {
    return (
      <div className={`message-row message-row-user ${sourceTag ? 'message-row-worker-report' : ''} ${mt} px-3 sm:px-6 lg:px-8`}>
        {sourceBadge}
        <div className="msg user text-sm">
          {rawViewEnabled ? (
            <RawMessageText content={message.content} className="text-sm" />
          ) : (
            <MarkdownRenderer
              content={message.content}
              attachmentIds={attachmentIds}
              className="text-sm"
            />
          )}
        </div>
        <MessageTimestamp ts={message.ts} className="mt-0.5" />
        {actions}
      </div>
    );
  }

  // Assistant messages — no bubble, left-aligned, full-width markdown flow
  return (
    <div className={`message-row message-row-assistant ${sourceTag ? 'message-row-worker-report' : ''} ${mt} px-3 sm:px-6 lg:px-8`}>
      {sourceBadge}
      <div className="msg assistant text-sm leading-relaxed">
        {rawViewEnabled ? (
          <RawMessageText content={message.content} />
        ) : (
          <MarkdownRenderer
            content={message.content}
            attachmentIds={attachmentIds}
          />
        )}
      </div>
      <MessageTimestamp ts={message.ts} className="mt-0.5" />
    </div>
  );
});

/**
 * Group consecutive tool and thinking messages into semantic display rows.
 * Other roles end the current group so blocks never cross a message boundary.
 */
export function groupMessages(
  messages: Message[],
  mergeConsecutiveNonBodyBlocks = false,
  timestampFlashMessages?: ReadonlySet<Message>,
  searchTargetMessageId?: string | null,
): GroupedItem[] {
  const grouped: GroupedItem[] = [];

  const appendToGroup = (group: GroupDisplayItem, message: Message) => {
    group.items.push(message);
    const validTs = message.ts && isValidMessageTs(message.ts) ? message.ts : undefined;
    if (validTs) group.latestTs = validTs;
    if (timestampFlashMessages?.has(message) && validTs) {
      const flashKey = getMessageIdentity(message);
      group.flashKey = flashKey;
      group.flashKeys = [...(group.flashKeys ?? []), flashKey];
    }
  };

  if (mergeConsecutiveNonBodyBlocks) {
    let currentNonBodyGroup: Message[] | null = null;

    for (const msg of messages) {
      if (searchTargetMessageId && msg.messageId === searchTargetMessageId) {
        currentNonBodyGroup = null;
        grouped.push(msg);
        continue;
      }
      if (msg.role === 'tool' || msg.role === 'thinking') {
        if (!currentNonBodyGroup) {
          currentNonBodyGroup = [];
          grouped.push({ type: 'non_body_group', items: currentNonBodyGroup });
        }
        appendToGroup(grouped[grouped.length - 1] as GroupDisplayItem, msg);
      } else {
        currentNonBodyGroup = null;
        grouped.push(msg);
      }
    }

    return grouped;
  }

  let currentToolGroup: Message[] | null = null;
  let currentThinkingGroup: Message[] | null = null;

  for (const msg of messages) {
    if (searchTargetMessageId && msg.messageId === searchTargetMessageId) {
      currentToolGroup = null;
      currentThinkingGroup = null;
      grouped.push(msg);
      continue;
    }
    if (msg.role === 'tool') {
      currentThinkingGroup = null;
      if (!currentToolGroup) {
        currentToolGroup = [];
        grouped.push({ type: 'tool_group', items: currentToolGroup });
      }
      appendToGroup(grouped[grouped.length - 1] as GroupDisplayItem, msg);
    } else if (msg.role === 'thinking') {
      currentToolGroup = null;
      if (!currentThinkingGroup) {
        currentThinkingGroup = [];
        grouped.push({ type: 'thinking_group', items: currentThinkingGroup });
      }
      appendToGroup(grouped[grouped.length - 1] as GroupDisplayItem, msg);
    } else {
      currentToolGroup = null;
      currentThinkingGroup = null;
      grouped.push(msg);
    }
  }

  return grouped;
}

interface MessageDisplayItemProps {
  item: GroupedItem;
  prevRole?: PrevRole;
  onTimestampFlashConsumed?: (flashKeys: readonly string[]) => void;
  searchTargetMessageId?: string | null;
}

export const MessageDisplayItem = memo(function MessageDisplayItem({
  item,
  prevRole = null,
  onTimestampFlashConsumed,
  searchTargetMessageId,
}: MessageDisplayItemProps) {
  if (!('type' in item) && item.messageId === searchTargetMessageId &&
      (item.role === 'tool' || item.role === 'thinking')) {
    return <div className="px-3 sm:px-6 lg:px-8 py-2" data-search-expanded-role={item.role}>
      <div className="text-xs text-text-tertiary">{item.role}</div>
      <MarkdownRenderer content={item.content} />
    </div>;
  }
  if ('type' in item) {
    if (item.type === 'non_body_group') {
      const firstRole = item.items[0]?.role === 'thinking' ? 'thinking' : 'tool';
      return (
        <div className={`${marginTopClass(firstRole, prevRole)} pb-3 px-3 sm:px-6 lg:px-8`}>
          <NonBodyGroup
            items={item.items}
            latestTs={item.latestTs}
            timestampsComputed
            flashKey={item.flashKey}
            flashKeys={item.flashKeys}
            onTimestampFlashConsumed={onTimestampFlashConsumed}
          />
        </div>
      );
    }
    if (item.type === 'tool_group') {
      return (
        <div className={`${marginTopClass('tool', prevRole)} pb-3 px-3 sm:px-6 lg:px-8`}>
          <ToolGroup
            items={item.items}
            latestTs={item.latestTs}
            timestampsComputed
            flashKey={item.flashKey}
            flashKeys={item.flashKeys}
            onTimestampFlashConsumed={onTimestampFlashConsumed}
          />
        </div>
      );
    }
    return (
      <div className={`${marginTopClass('thinking', prevRole)} px-3 sm:px-6 lg:px-8`}>
        <ThinkingGroup
          items={item.items}
          latestTs={item.latestTs}
          timestampsComputed
          flashKey={item.flashKey}
          flashKeys={item.flashKeys}
          onTimestampFlashConsumed={onTimestampFlashConsumed}
        />
      </div>
    );
  }
  return <MessageBubble message={item as Message} prevRole={prevRole} />;
});

import { useEffect, useMemo, useRef, useState } from 'react';
import { Loader2 } from 'lucide-react';
import { Button } from '@/components/ui/Button';
import { Modal } from '@/components/ui/Modal';
import { useSessionStore } from '@/stores/sessionStore';
import { fetchRewindJobStatus } from '@/services/api';
import type { Message, RewindScope, StreamEvent } from '@/types';

export const REWIND_STAGE_LABELS: Record<string, string> = {
  starting: '\u51c6\u5907\u4e2d',
  resuming: '\u6253\u5f00\u4f1a\u8bdd',
  'rewinding-files': '\u56de\u6eda\u6587\u4ef6',
  truncating: '\u622a\u65ad\u5bf9\u8bdd',
  completed: '\u5b8c\u6210',
  failed: '\u5931\u8d25',
};

const MODAL_STAGE_LABELS: Record<string, string> = {
  starting: '\u6b63\u5728\u542f\u52a8\u56de\u6eda\u2026',
  resuming: '\u6b63\u5728\u6062\u590d\u4f1a\u8bdd\u526f\u672c\u2026',
  'rewinding-files': '\u6b63\u5728\u56de\u6eda\u4ee3\u7801\u2026',
  truncating: '\u6b63\u5728\u622a\u65ad\u5bf9\u8bdd',
  completed: '\u5b8c\u6210',
  failed: '\u5931\u8d25',
};

const SCOPE_OPTIONS: Array<{ value: RewindScope; label: string; hint: string }> = [
  { value: 1, label: '对话 + 代码', hint: '对话与代码一起回滚到这条消息' },
  { value: 2, label: '仅对话', hint: '只回滚对话，文件保持当前状态' },
  { value: 3, label: '仅代码', hint: '只回滚代码，对话保持完整' },
];

/** Extract mutated file paths from one tool message body. Handles both the
 *  FileChange shape ("tool call: FileChange\nargs: {...}" / "FileChange({...})",
 *  mirrored from ToolGroup) and cbc's own mutating file tools (Write/Edit
 *  carry "file_path", which is what real cbc sessions actually contain.
 *  Scanning only FileChange made the affected-files list always empty for
 *  cbc sessions, so the modal claimed "no code changes" on every anchor. */
function extractFileChangePaths(content: string): string[] {
  if (!content) return [];
  let name = '';
  let argsText = '';
  const callMatch = content.match(/^tool call:\s*(.+?)(?:\r?\n|\r)args:\s*([\s\S]*)$/);
  if (callMatch) {
    name = callMatch[1]?.split('\n')[0]?.trim() || '';
    argsText = callMatch[2]?.trim() || '';
  } else {
    const modernMatch = content.match(/^([^(]+)\(([\s\S]*)\)$/);
    if (!modernMatch) return [];
    name = (modernMatch[1] || '').trim();
    argsText = modernMatch[2] || '';
  }
  if (!argsText) return [];
  const normalizedName = name.trim().toLowerCase();
  try {
    const args = JSON.parse(argsText) as Record<string, unknown>;
    if (!args || typeof args !== 'object') return [];
    if (normalizedName === 'filechange') {
      if (!Array.isArray(args.changes)) return [];
      return args.changes
        .map((change) => {
          if (!change || typeof change !== 'object') return '';
          const record = change as Record<string, unknown>;
          return typeof record.path === 'string' ? record.path : '';
        })
        .filter(Boolean);
    }
    if (['write', 'edit', 'multiedit', 'notebookedit'].includes(normalizedName)) {
      const path = args.file_path ?? args.filePath;
      return typeof path === 'string' && path ? [path] : [];
    }
    return [];
  } catch {
    return [];
  }
}

interface RewindConfirmModalProps {
  message: Message;
  onClose: () => void;
}

export function RewindConfirmModal({ message, onClose }: RewindConfirmModalProps) {
  const [scope, setScope] = useState<RewindScope>(1);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const activeRewinds = useSessionStore((s) => s.activeRewinds);
  const currentSessionId = useSessionStore((s) => s.currentSessionId);
  const rewindCurrentMessage = useSessionStore((s) => s.rewindCurrentMessage);
  const minimizeRewind = useSessionStore((s) => s.minimizeRewind);
  const dismissRewind = useSessionStore((s) => s.dismissRewind);
  const confirmRef = useRef<HTMLButtonElement>(null);
  // The rewind this modal is showing progress for. Keyed to the session the
  // confirm was started from so a concurrent job on ANOTHER session can never
  // hijack this popup.
  const activeRewind = activeRewinds.find((item) => item.sessionId === currentSessionId) ?? null;

  useEffect(() => {
    confirmRef.current?.focus();
  }, []);

  // Files changed after the anchor message = the code this rewind may
  // restore. Computed lazily on open (currentMessages scan per bubble render
  // would be wasted work).
  const affectedFiles = useMemo(() => {
    const messages = useSessionStore.getState().currentMessages;
    const index = messages.indexOf(message);
    if (index < 0) return [] as string[];
    const paths = new Set<string>();
    for (const item of messages.slice(index + 1)) {
      if (item.role !== 'tool') continue;
      for (const path of extractFileChangePaths(item.content)) paths.add(path);
    }
    return [...paths];
  }, [message]);

  const running = activeRewind?.status === 'running';
  const failed = activeRewind?.status === 'failed';

  // Polling fallback: while the job runs, refetch the persisted rewind
  // record every 2s so a dropped WS event can never leave the job without
  // progress. WS events remain the fast path; re-applying an already-seen
  // stage is idempotent in applyRewindProgress. Runs independently of
  // whether the popup is open ? closing it must not stop the fallback.
  const jobId = activeRewind?.jobId || '';
  const jobSessionId = activeRewind?.sessionId || '';
  useEffect(() => {
    if (!running || !jobId) return;
    let cancelled = false;
    const poll = async () => {
      try {
        const record = await fetchRewindJobStatus(jobSessionId, jobId);
        if (cancelled) return;
        useSessionStore.getState().applyRewindProgress({
          type: 'session.rewind.progress',
          jobId,
          sessionId: jobSessionId,
          stage: record.stage || undefined,
          error: typeof record.error === 'string' ? record.error : record.error?.message,
          newSessionId: record.newSessionId || undefined,
        } as StreamEvent);
      } catch {
        // Best-effort fallback; the next tick retries.
      }
    };
    const timer = setInterval(() => void poll(), 2000);
    return () => {
      cancelled = true;
      clearInterval(timer);
    };
  }, [running, jobId, jobSessionId]);

  const codeScopeUnavailable = scope !== 2 && affectedFiles.length === 0;

  const onConfirm = async () => {
    setSubmitError(null);
    try {
      await rewindCurrentMessage(message, scope);
    } catch (error) {
      setSubmitError(error instanceof Error ? error.message : '\u64a4\u56de\u5931\u8d25');
    }
  };

  // 「后台运行」 closes the popup, keeping the job alive; this is not a cancel.
  // entry is removed, so WS events / polling continue and completion still
  // jumps and prefills.
  const handleRunInBackground = () => {
    if (activeRewind?.jobId) minimizeRewind(activeRewind.jobId);
    onClose();
  };

  const handleClose = () => {
    if (running) return;
    if (failed) dismissRewind(activeRewind?.jobId);
    onClose();
  };

  return (
    <Modal open onClose={handleClose} title="撤回确认" size="sm">
      <div className="space-y-3 text-sm text-text-secondary">
        {failed ? (
          <>
            <p className="text-danger">{activeRewind?.error || '撤回失败'}</p>
            <div className="flex flex-wrap justify-end gap-2 pt-2">
              <Button type="button" variant="ghost" onClick={handleClose}>
                关闭
              </Button>
            </div>
          </>
        ) : running ? (
          <>
            <div className="flex items-center gap-2 py-4 text-text-primary">
              <Loader2 size={16} className="animate-spin" />
              <span>{MODAL_STAGE_LABELS[activeRewind?.stage || 'starting'] || '正在处理…'}</span>
            </div>
            <p className="text-xs text-text-tertiary">
              撤回正在后台运行，关闭此窗口不会取消任务；完成后可在输入框上方的状态条中查看进度。
            </p>
            <div className="flex flex-wrap justify-end gap-2 pt-2">
              <Button type="button" variant="ghost" onClick={handleRunInBackground}>
                后台运行
              </Button>
            </div>
          </>
        ) : (
          <>
            <p>
              撤回会创建新的分支会话，原会话保持不变。请选择回滚范围：
            </p>
            <div className="space-y-1.5">
              {SCOPE_OPTIONS.map((option) => (
                <label
                  key={option.value}
                  className="flex cursor-pointer items-start gap-2 rounded border border-border-default px-2 py-1.5 hover:bg-bg-tertiary"
                >
                  <input
                    type="radio"
                    name="rewind-scope"
                    className="mt-0.5"
                    checked={scope === option.value}
                    onChange={() => setScope(option.value)}
                  />
                  <span>
                    <span className="block text-text-primary">{option.label}</span>
                    <span className="block text-xs text-text-tertiary">{option.hint}</span>
                  </span>
                </label>
              ))}
            </div>
            {affectedFiles.length > 0 ? (
              <div>
                <p className="mb-1 text-xs text-text-tertiary">
                  这条消息之后被修改的文件：
                </p>
                <div className="max-h-32 overflow-y-auto rounded border border-border-default bg-bg-tertiary px-2 py-1.5">
                  {affectedFiles.map((path) => (
                    <code key={path} className="block break-all text-xs text-text-primary">
                      {path}
                    </code>
                  ))}
                </div>
              </div>
            ) : (
              <p className="text-xs text-text-tertiary">这条消息之后未检测到文件变更。</p>
            )}
            {codeScopeUnavailable && (
              <p className="text-xs text-warning">
                该检查点没有代码变更，无法仅回滚代码；请改选「对话 + 代码」或「仅对话」。
              </p>
            )}
            <p className="text-xs text-text-tertiary">
              仅回滚 cbc 自己文件编辑工具造成的改动；bash 命令与手动编辑的文件不会回滚。
            </p>
            {submitError && <p className="text-xs text-danger">{submitError}</p>}
            <div className="flex flex-wrap justify-end gap-2 pt-2">
              <Button type="button" variant="ghost" onClick={handleClose}>
                取消
              </Button>
              <Button
                ref={confirmRef}
                type="button"
                variant="primary"
                onClick={() => void onConfirm()}
              >
                确认撤回
              </Button>
            </div>
          </>
        )}
      </div>
    </Modal>
  );
}

import { createPortal } from 'react-dom';
import { useCallback, useEffect, useLayoutEffect, useRef, useState, type RefObject } from 'react';
import {
  useCurrentSession,
  useSessionStore,
  type SessionSettingPatch,
} from '@/stores/sessionStore';
import { useWorkerStore } from '@/stores/workerStore';
import { useUIStore } from '@/stores/uiStore';
import { useAdapterStore } from '@/stores/adapterStore';
import { Button } from '@/components/ui/Button';
import { ModelSelect } from '@/components/ui/ModelSelect';
import { fetchSession } from '@/services/api';
import type { AdapterConfig, PermissionMode, Session } from '@/types';
import { FreshnessStatus } from '@/components/session/FreshnessStatus';

interface SettingsPopoverProps {
  open: boolean;
  onClose: () => void;
  anchorRef?: RefObject<HTMLElement | null>;
}

function supportsSetting(config: AdapterConfig | null, name: string): boolean {
  if (!config?.supportedSettings) return false;
  return config.supportedSettings.includes(name);
}

function pickSettings(session: Session): SessionSettingPatch {
  return {
    ...(Object.prototype.hasOwnProperty.call(session, 'model') ? { model: session.model } : {}),
    ...(Object.prototype.hasOwnProperty.call(session, 'permissionMode')
      ? { permissionMode: session.permissionMode }
      : {}),
    ...(Object.prototype.hasOwnProperty.call(session, 'alwaysThinkingEnabled')
      ? { alwaysThinkingEnabled: session.alwaysThinkingEnabled }
      : {}),
    ...(Object.prototype.hasOwnProperty.call(session, 'effort') ? { effort: session.effort } : {}),
    ...(Object.prototype.hasOwnProperty.call(session, 'outputMode')
      ? { outputMode: session.outputMode }
      : {}),
    ...(Object.prototype.hasOwnProperty.call(session, 'modelContextWindow')
      ? { modelContextWindow: session.modelContextWindow }
      : {}),
    ...(Object.prototype.hasOwnProperty.call(session, 'modelAutoCompactTokenLimit')
      ? { modelAutoCompactTokenLimit: session.modelAutoCompactTokenLimit }
      : {}),
  };
}

/**
 * Upward-expanding settings popover anchored to the toolbar's gear button
 * (rendered `absolute bottom-full`, so it appears above the input row and
 * never covers the textarea). Compact replacement for the old right-side
 * SettingsPanel: model / permission mode / thinking+effort / worker actions.
 */
export function SettingsPopover({ open, onClose, anchorRef }: SettingsPopoverProps) {
  const session = useCurrentSession();
  const currentWorker = useWorkerStore((s) => s.currentWorker);
  const showToast = useUIStore((s) => s.showToast);
  const { restart, killCurrent, interrupt, takeover } = useWorkerStore();
  const config = useAdapterStore((s) => s.getConfig());
  const applySettings = useAdapterStore((s) => s.applySettings);
  const loadSessions = useSessionStore((s) => s.loadSessions);
  const patchSessionSettings = useSessionStore((s) => s.patchSessionSettings);
  const settingMutation = useSessionStore((s) =>
    session?.id ? s.sessionSettingMutations[session.id] : undefined,
  );

  // The sidebar list is summary=1 driven and does NOT carry model /
  // permissionMode / alwaysThinkingEnabled / effort — fetch the full session
  // on open so the editor shows the real values (on-demand detail, same as
  // Manage/Postbox). The settings fields are also merged into the store so the
  // toolbar pills / effort select reflect them too.
  const [detailSession, setDetailSession] = useState<Session | null>(null);
  const [moreOpen, setMoreOpen] = useState(false);
  const [contextWindowInput, setContextWindowInput] = useState('');
  const [autoCompactInput, setAutoCompactInput] = useState('');
  const [contextWindowError, setContextWindowError] = useState('');
  const [autoCompactError, setAutoCompactError] = useState('');
  const [restoringCodexDefaults, setRestoringCodexDefaults] = useState(false);
  const [popoverPosition, setPopoverPosition] = useState<{ left: number; bottom: number } | null>(
    null,
  );
  const detailRequestSeq = useRef(0);
  const [detailLoading, setDetailLoading] = useState(false);
  const [detailRefreshing, setDetailRefreshing] = useState(false);
  const [detailError, setDetailError] = useState<string | null>(null);
  const [detailRetrySeq, setDetailRetrySeq] = useState(0);
  const updatePopoverPosition = () => {
    const rect = anchorRef?.current?.getBoundingClientRect();
    if (!rect) return;
    setPopoverPosition({ left: rect.left, bottom: window.innerHeight - rect.top + 4 });
  };

  useLayoutEffect(() => {
    if (!open) {
      setPopoverPosition(null);
      return;
    }
    updatePopoverPosition();
  }, [open, anchorRef]);

  useEffect(() => {
    if (!open) return;
    const update = () => updatePopoverPosition();
    window.addEventListener('resize', update);
    window.addEventListener('scroll', update, true);
    return () => {
      window.removeEventListener('resize', update);
      window.removeEventListener('scroll', update, true);
    };
  }, [open, anchorRef]);
  useEffect(() => {
    if (!open || !session?.id) return;
    const requestSeq = (detailRequestSeq.current += 1);
    const sessionId = session.id;
    setDetailSession(null);
    setDetailLoading(true);
    setDetailRefreshing(false);
    setDetailError(null);
    setMoreOpen(false);
    setContextWindowInput(session.modelContextWindow?.toString() ?? '');
    setAutoCompactInput(session.modelAutoCompactTokenLimit?.toString() ?? '');
    setContextWindowError('');
    setAutoCompactError('');
    fetchSession(session.id)
      .then((full) => {
        if (
          detailRequestSeq.current !== requestSeq ||
          useSessionStore.getState().currentSessionId !== sessionId
        ) return;
        setDetailSession(full);
        setDetailLoading(false);
        setDetailRefreshing(false);
        setContextWindowInput(full.modelContextWindow?.toString() ?? '');
        setAutoCompactInput(full.modelAutoCompactTokenLimit?.toString() ?? '');
        useSessionStore.getState().updateSession(full.id, {
          model: full.model ?? undefined,
          permissionMode: full.permissionMode ?? undefined,
          alwaysThinkingEnabled: full.alwaysThinkingEnabled,
          effort: full.effort,
          modelContextWindow: full.modelContextWindow,
          modelAutoCompactTokenLimit: full.modelAutoCompactTokenLimit,
          workdir: full.workdir,
        });
      })
      .catch((error) => {
        if (detailRequestSeq.current !== requestSeq) return;
        setDetailLoading(false);
        setDetailRefreshing(false);
        setDetailError(error instanceof Error ? error.message : 'Session metadata unavailable');
        setDetailSession(null);
      });
  }, [open, session?.id, detailRetrySeq]);

  // Same per-session effective-worker logic as TopBar/SettingsPanel.
  const effectiveWorkerId =
    (session?.workerId && session.workerStatus ? session.workerId : null) ||
    (currentWorker && currentWorker.sessionId === session?.id ? currentWorker.id : null) ||
    null;

  const applySetting = useCallback(
    async (key: string, value: unknown): Promise<boolean> => {
      if (!session) return false;
      const patch: SessionSettingPatch = { [key]: value } as SessionSettingPatch;
      // Codex exposes model-specific reasoning levels. Clear an effort that
      // the newly selected model cannot accept; empty means native default.
      if (key === 'model' && config?.modelEfforts) {
        const nextEfforts = config.modelEfforts[String(value)];
        const currentEffort = (detailSession ?? session).effort || '';
        if (nextEfforts && currentEffort && !nextEfforts.includes(currentEffort)) {
          patch.effort = '';
        }
      }
      try {
        // Reflect the change locally before awaiting PATCH so every control
        // and the sidebar can show the selection without network latency.
        setDetailSession((d) => (d ? { ...d, ...patch } : d));
        const result = await patchSessionSettings(session.id, patch, applySettings);
        const latest = useSessionStore.getState().sessions.find((item) => item.id === session.id);
        if (latest) {
          setDetailSession((d) => (d ? { ...d, ...pickSettings(latest) } : d));
        }
        // Snapshot reconciliation is background work and must not delay the
        // optimistic render or make a closed popover observable.
        void loadSessions();
        // Process-affecting settings (output_mode / model / mcp …) require a
        // worker restart to take effect. When a worker is NOT running the
        // backend flags `requireRestart`; surface it so the user knows the
        // change applies on next spawn / when the worker goes idle.
        if (result.applied && (result.response as { requireRestart?: boolean }).requireRestart) {
          showToast('配置已保存，Worker 将自动 respawn 后生效；当前 turn 结束后切换', 'info');
        }
        return true;
      } catch (e) {
        showToast((e as Error).message || 'Failed', 'error');
        return false;
      }
    },
    [session, detailSession, config, effectiveWorkerId, applySettings, patchSessionSettings, loadSessions, showToast],
  );

  const updateCodexNumber = async (
    key: 'modelContextWindow' | 'modelAutoCompactTokenLimit',
    raw: string,
    setError: (value: string) => void,
  ) => {
    if (!/^[1-9]\d*$/.test(raw)) {
      setError('请输入正整数；如需交给 Codex 默认值，请使用“恢复默认”');
      return;
    }
    const parsed = Number(raw);
    if (!Number.isSafeInteger(parsed) || parsed <= 0) {
      setError('请输入 JavaScript 安全范围内的正整数');
      return;
    }
    setError('');
    await applySetting(key, parsed);
  };

  const restoreCodexDefaults = async () => {
    if (!session || restoringCodexDefaults) return;
    setRestoringCodexDefaults(true);
    try {
      const result = await patchSessionSettings(session.id, {
        modelContextWindow: null,
        modelAutoCompactTokenLimit: null,
      }, applySettings);
      if (result.applied) {
        setDetailSession((d) =>
          d
            ? {
                ...d,
                modelContextWindow: null,
                modelAutoCompactTokenLimit: null,
              }
            : d,
        );
      }
      void loadSessions();
      if (result.applied && !(result.response as { error?: string }).error) {
        setContextWindowInput('');
        setAutoCompactInput('');
        setContextWindowError('');
        setAutoCompactError('');
        showToast('已清除 Codex 上下文覆盖，Worker 将自动 respawn 后使用模型默认值', 'info');
      }
    } catch (e) {
      showToast((e as Error).message || 'Failed', 'error');
    } finally {
      setRestoringCodexDefaults(false);
    }
  };

  // Close on any outside pointer. The gear wrapper and the popover itself both
  // carry data-settings-popover; ModelSelect's menu is a separate body portal,
  // so its existing data-model-select-menu boundary must also be kept inside.
  // Capture phase makes this reliable for controls elsewhere in the app that
  // stop propagation, and pointerdown covers touch as well as mouse input.
  useEffect(() => {
    if (!open) return;
    const isInsideSettings = (e: Event) =>
      e
        .composedPath()
        .some(
          (node) =>
            node instanceof Element &&
            (node.matches('[data-settings-popover]') || node.matches('[data-model-select-menu]')),
        );
    const handlePointerDown = (e: PointerEvent) => {
      if (!isInsideSettings(e)) onClose();
    };
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    document.addEventListener('pointerdown', handlePointerDown, true);
    document.addEventListener('keydown', handleKeyDown);
    return () => {
      document.removeEventListener('pointerdown', handlePointerDown, true);
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [open, onClose]);

  if (!open || !session || !config) return null;

  // Prefer the on-demand full session when loaded; fall back to the store's
  // (summary) session for id / workerStatus etc.
  // The on-demand detail object is intentionally retained for fields omitted
  // by summary=1, but the store is the live source for optimistic settings.
  // Overlay only fields that are actually present so a summary cannot erase
  // detail values while a PATCH is pending.
  const s = detailSession?.id === session.id
    ? { ...detailSession, ...pickSettings(session) }
    : session;

  const models = config.models || [];
  const currentModel = s.model || config.defaultModel;
  const modelOptions = models.includes(currentModel) ? models : [currentModel, ...models];
  const modes = config.permissionModes || [];
  const showMode = supportsSetting(config, 'permissionMode');
  const showThinking = supportsSetting(config, 'thinking');
  const showEffort =
    supportsSetting(config, 'effort') && (!showThinking || !!s.alwaysThinkingEnabled);
  const modelEfforts = config.modelEfforts?.[currentModel];
  const effortValues = modelEfforts ? ['', ...modelEfforts] : config.effortValues || [];
  // opencode's effort list starts with "" (unset sentinel); filter it out so
  // the dropdown never renders a blank <option>, and surface it as a clear
  // "默认" placeholder instead.
  const validEffortValues = effortValues.filter((v) => v && String(v).trim() !== '');
  const hadEmpty = effortValues.length !== validEffortValues.length;
  const currentEffort =
    s.effort && validEffortValues.includes(s.effort.trim())
      ? s.effort
      : hadEmpty
        ? ''
        : (validEffortValues[0] ?? '');
  // Output Mode selector is shown only when the adapter exposes more than one
  // execution mode (e.g. cbc: ["stream","oneshot"]). Single-mode adapters
  // (kimi/opencode: ["stream"]) never render it — they cannot switch.
  const execModes = config.executionModes || ['stream'];
  const showOutputMode = execModes.length > 1;
  const currentOutputMode =
    s.outputMode ?? (execModes.includes('stream') ? 'stream' : execModes[0]);
  const showCodexContext =
    s.adapter === 'codex' &&
    supportsSetting(config, 'modelContextWindow') &&
    supportsSetting(config, 'modelAutoCompactTokenLimit');
  const hasCodexOverrides = s.modelContextWindow != null || s.modelAutoCompactTokenLimit != null;

  if (!popoverPosition) return null;

  return createPortal(
    <div
      data-settings-popover
      style={{ position: 'fixed', left: popoverPosition.left, bottom: popoverPosition.bottom }}
      className="z-[60] mb-1 w-72 max-w-[calc(100vw-1rem)] max-h-[60vh] overflow-y-auto rounded-md border border-border-default bg-bg-primary shadow-xl p-3 space-y-3"
    >
      <FreshnessStatus
        state={detailError ? 'error' : detailLoading ? (detailRefreshing ? 'refreshing' : 'loading') : detailSession ? 'updated' : 'cached'}
        updatedAt={detailSession?.updatedAt ?? session.updatedAt}
        source={detailSession ? 'session metadata' : 'session summary cache'}
        error={detailError}
        onRetry={detailError ? () => setDetailRetrySeq((value) => value + 1) : undefined}
      />
      {settingMutation?.pending && (
        <div data-settings-pending className="text-[11px] text-text-muted" aria-live="polite">
          保存中…
        </div>
      )}
      {!settingMutation?.pending && settingMutation?.error && (
        <div data-settings-error className="text-[11px] text-danger" role="status">
          {settingMutation.error}
        </div>
      )}
      {/* Model — ModelSelect 支持关键字过滤（opencode 几十上百个模型时可快速检索） */}
      <div>
        <label className="block text-xs text-text-secondary mb-1">Model</label>
        <ModelSelect
          value={currentModel}
          options={modelOptions}
          onChange={(v) => applySetting('model', v)}
        />
      </div>

      {/* Permission Mode */}
      {showMode && (
        <div>
          <label className="block text-xs text-text-secondary mb-1">Permission Mode</label>
          <select
            value={s.permissionMode || config.defaultPermissionMode}
            onChange={(e) => applySetting('permissionMode', e.target.value)}
            className="w-full rounded border border-border-default bg-bg-tertiary px-2 py-1 text-xs text-text-primary"
          >
            {modes.map((p: PermissionMode) => (
              <option key={p.value} value={p.value}>
                {p.label}
              </option>
            ))}
          </select>
        </div>
      )}

      {/* Codex context controls stay behind a compact More disclosure. */}
      {showCodexContext && (
        <div className="border-t border-border-muted pt-2">
          <button
            type="button"
            className="flex w-full items-center justify-between text-left text-xs font-semibold text-text-secondary"
            aria-expanded={moreOpen}
            onClick={() => setMoreOpen((value) => !value)}
          >
            <span>More</span>
            <span aria-hidden="true" className="text-text-muted">
              {moreOpen ? '▾' : '▸'}
            </span>
          </button>
          {moreOpen && (
            <div className="mt-2 space-y-2">
              <p className="text-[11px] leading-4 text-text-muted">
                修改后需 Worker 自动 respawn/restart 后生效；当前 turn 不热更新。
              </p>
              <label className="block text-xs text-text-secondary">
                <span className="mb-1 block">Context window</span>
                <input
                  type="number"
                  min={1}
                  step={1}
                  inputMode="numeric"
                  value={contextWindowInput}
                  aria-label="model_context_window"
                  onChange={(e) => {
                    setContextWindowInput(e.target.value);
                    if (e.target.value === '' || /^[1-9]\d*$/.test(e.target.value)) {
                      setContextWindowError('');
                    } else {
                      setContextWindowError('请输入正整数');
                    }
                  }}
                  onBlur={() =>
                    updateCodexNumber(
                      'modelContextWindow',
                      contextWindowInput,
                      setContextWindowError,
                    )
                  }
                  className="w-full rounded border border-border-default bg-bg-tertiary px-2 py-1 text-xs text-text-primary"
                />
                {contextWindowError && (
                  <span className="mt-1 block text-[11px] text-danger">{contextWindowError}</span>
                )}
              </label>
              <label className="block text-xs text-text-secondary">
                <span className="mb-1 block">Auto-compact token limit</span>
                <input
                  type="number"
                  min={1}
                  step={1}
                  inputMode="numeric"
                  value={autoCompactInput}
                  aria-label="model_auto_compact_token_limit"
                  onChange={(e) => {
                    setAutoCompactInput(e.target.value);
                    if (e.target.value === '' || /^[1-9]\d*$/.test(e.target.value)) {
                      setAutoCompactError('');
                    } else {
                      setAutoCompactError('请输入正整数');
                    }
                  }}
                  onBlur={() =>
                    updateCodexNumber(
                      'modelAutoCompactTokenLimit',
                      autoCompactInput,
                      setAutoCompactError,
                    )
                  }
                  className="w-full rounded border border-border-default bg-bg-tertiary px-2 py-1 text-xs text-text-primary"
                />
                {autoCompactError && (
                  <span className="mt-1 block text-[11px] text-danger">{autoCompactError}</span>
                )}
              </label>
              <Button
                variant="secondary"
                size="sm"
                disabled={!hasCodexOverrides || restoringCodexDefaults}
                onClick={restoreCodexDefaults}
              >
                {restoringCodexDefaults ? 'Restoring…' : 'Restore defaults'}
              </Button>
            </div>
          )}
        </div>
      )}

      {/* Thinking + Effort */}
      {showThinking && (
        <div className="flex flex-wrap items-center gap-x-4 gap-y-2">
          <label className="flex items-center gap-2 text-xs text-text-secondary cursor-pointer">
            <input
              type="checkbox"
              checked={!!s.alwaysThinkingEnabled}
              onChange={(e) => applySetting('alwaysThinkingEnabled', e.target.checked)}
              className="rounded border-border-default bg-bg-tertiary"
            />
            Always Thinking
          </label>
          {showEffort && validEffortValues.length > 0 && (
            <label className="flex items-center gap-1.5 text-xs text-text-secondary">
              <span className="whitespace-nowrap">Effort</span>
              <select
                value={currentEffort}
                onChange={(e) => applySetting('effort', e.target.value)}
                className="rounded border border-border-default bg-bg-tertiary px-2 py-1 text-xs text-text-primary"
              >
                {hadEmpty && <option value="">默认</option>}
                {validEffortValues.map((v) => (
                  <option key={v} value={v}>
                    {v}
                  </option>
                ))}
              </select>
            </label>
          )}
        </div>
      )}

      {/* Output Mode (execution mode): only adapters with >1 mode offer it */}
      {showOutputMode && (
        <div>
          <label className="block text-xs text-text-secondary mb-1">Output Mode</label>
          <select
            value={currentOutputMode}
            onChange={(e) => applySetting('outputMode', e.target.value)}
            className="w-full rounded border border-border-default bg-bg-tertiary px-2 py-1 text-xs text-text-primary"
          >
            {execModes.map((m) => (
              <option key={m} value={m}>
                {m}
              </option>
            ))}
          </select>
        </div>
      )}

      <div className="border-t border-border-muted" />

      {/* Worker actions */}
      <div>
        <h4 className="text-xs font-semibold text-text-secondary mb-2">Worker</h4>
        <div className="flex flex-col gap-1.5">
          <Button
            variant="secondary"
            size="sm"
            onClick={() => {
              if (!session?.id) return;
              // The session-level endpoint decides atomically whether this is
              // a restart or a start; effectiveWorkerId may be stale after a
              // watchdog destroy and must not be used for control routing.
              restart(session.id)
                .then(() => showToast('Worker restarted or started'))
                .catch((e) => showToast(e.message, 'error'));
            }}
          >
            ⟳ Restart
          </Button>
          {effectiveWorkerId && (
            <>
              <Button
                variant="secondary"
                size="sm"
                onClick={() =>
                  interrupt(session.id)
                    .then(() => showToast('Interrupt sent'))
                    .catch((e) => showToast(e.message, 'error'))
                }
              >
                ⊘ Interrupt
              </Button>
              <Button
                variant="secondary"
                size="sm"
                onClick={() =>
                  takeover(session.id)
                    .then(() => showToast('PowerShell opened for takeover'))
                    .catch((e) => showToast(e.message, 'error'))
                }
              >
                ⤓ Takeover
              </Button>
              <Button
                variant="danger"
                size="sm"
                onClick={() => {
                  if (!confirm(`Kill worker ${effectiveWorkerId}?`)) return;
                  killCurrent(session.id)
                    .then(() => showToast('Kill sent'))
                    .catch((e) => showToast(e.message, 'error'));
                }}
              >
                ✕ Kill
              </Button>
            </>
          )}
        </div>
      </div>
    </div>,
    document.body,
  );
}

import { useRef, useEffect, useCallback } from 'react';
import { useDetailStore } from '@/stores/detailStore';
import { PanelHeader } from './PanelHeader';
import { MarkdownRenderer } from '@/components/chat/MarkdownRenderer';

export function DetailPanel() {
  const detailTarget = useDetailStore((s) => s.detailTarget);
  const panelWidth = useDetailStore((s) => s.panelWidth);
  const closeDetail = useDetailStore((s) => s.closeDetail);
  const setPanelWidth = useDetailStore((s) => s.setPanelWidth);
  const contentRef = useRef<HTMLDivElement>(null);

  const isResizing = useRef(false);

  // Auto-scroll to bottom when content changes
  useEffect(() => {
    if (detailTarget && contentRef.current) {
      contentRef.current.scrollTop = contentRef.current.scrollHeight;
    }
  }, [detailTarget?.content]);

  // Resize handle handlers
  const handleMouseDown = useCallback(
    (e: React.MouseEvent) => {
      e.preventDefault();
      isResizing.current = true;
      const startX = e.clientX;
      const startWidth = useDetailStore.getState().panelWidth;

      const handleMouseMove = (e: MouseEvent) => {
        if (!isResizing.current) return;
        const delta = startX - e.clientX;
        setPanelWidth(startWidth + delta);
      };

      const handleMouseUp = () => {
        isResizing.current = false;
        document.removeEventListener('mousemove', handleMouseMove);
        document.removeEventListener('mouseup', handleMouseUp);
        document.body.style.cursor = '';
        document.body.style.userSelect = '';
      };

      document.body.style.cursor = 'col-resize';
      document.body.style.userSelect = 'none';
      document.addEventListener('mousemove', handleMouseMove);
      document.addEventListener('mouseup', handleMouseUp);
    },
    [setPanelWidth],
  );

  if (!detailTarget) {
    return <aside className="w-0 overflow-hidden border-l-0" />;
  }

  const title = detailTarget.type === 'thinking' ? 'Thinking' : 'Tool';
  const subtitle = detailTarget.content
    ? detailTarget.content.replace(/\n/g, ' ').slice(0, 60)
    : '';

  return (
    <aside
      className="flex flex-col h-full border-l border-border-default bg-bg-secondary transition-[width] duration-[280ms] ease-in-out"
      style={{ width: panelWidth }}
    >
      {/* Resize handle on left edge */}
      <div
        className="absolute left-0 top-0 bottom-0 w-[4px] cursor-col-resize hover:bg-accent/50 z-10"
        style={{ marginLeft: -2 }}
        onMouseDown={handleMouseDown}
      />

      <PanelHeader title={title} subtitle={subtitle} onClose={closeDetail} />
      <div ref={contentRef} className="flex-1 overflow-y-auto p-4">
        {detailTarget.type === 'thinking' ? (
          <div className="text-sm text-text-secondary leading-relaxed">
            <MarkdownRenderer content={detailTarget.content} />
          </div>
        ) : (
          <pre className="text-sm text-text-secondary whitespace-pre-wrap leading-relaxed">
            {detailTarget.content}
          </pre>
        )}
      </div>
    </aside>
  );
}

import { useEffect, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Check, Copy, Download, MessageSquare, Save as SaveIcon } from 'lucide-react';
import { useMediaQuery } from '@/hooks/useMediaQuery';
import { useCurrentSession } from '@/stores/sessionStore';
import { useEditorStore } from '@/stores/editorStore';
import { useUIStore } from '@/stores/uiStore';
import { copyText } from '@/utils/clipboard';

interface EditorFileTopBarProps {
  /** Session-relative path used by backend operations and attachment queue. */
  operationPath: string;
  imagePreview?: boolean;
  imageDisplayName?: string;
  imageDownloadHref?: string;
}

export function getDisplayPath(workdir: string | null | undefined, operationPath: string): string {
  if (!workdir) return operationPath;

  // Pick the separator from the root syntax, then normalize every internal
  // separator in the workdir and operation path to that same style. In
  // particular, do not collapse the two leading separators of a UNC path.
  const driveRoot = /^([A-Za-z]:)([\\/])/.exec(workdir);
  const uncRoot = /^(\\\\|\/\/)/.exec(workdir);
  const separator = driveRoot?.[2] ?? uncRoot?.[1]?.[0] ?? (workdir.startsWith('/') ? '/' : workdir.includes('\\') ? '\\' : '/');
  const normalizedRest = (value: string) => value.replace(/[\\/]+/g, separator).replace(new RegExp(`${separator === '\\' ? '\\\\' : '\\/'}+$`), '');

  // Markdown links may open a server-absolute file. Do not prepend the
  // current Session workdir to an already absolute operation path.
  // Editor roots (CWD/Workspace/Temp) contribute absolute paths, so a POSIX
  // absolute operation path must not be re-parented under the workdir.
  const operationIsUnc = /^(\\\\|\/\/)/.test(operationPath);
  const operationIsDriveAbsolute = /^[A-Za-z]:[\\/]/.test(operationPath);
  if (operationIsUnc) {
    return `${separator}${separator}${operationPath.slice(2).replace(/[\\/]+/g, separator)}`;
  }
  if (operationIsDriveAbsolute) {
    return operationPath.replace(/[\\/]+/g, separator);
  }
  if (operationPath.startsWith('/') && workdir.startsWith('/')) {
    // A POSIX-workdir Session browsing an absolute POSIX root (CWD/Workspace/
    // Temp): show the absolute path instead of re-parenting it under the
    // workdir. A bare leading '/' with a Windows workdir stays workdir-relative
    // (existing Markdown-link behavior).
    return operationPath.replace(/\\/g, '/');
  }
  let normalizedWorkdir: string;
  if (driveRoot) {
    const rest = normalizedRest(workdir.slice(3));
    normalizedWorkdir = rest ? `${driveRoot[1]}${separator}${rest}` : `${driveRoot[1]}${separator}`;
  } else if (uncRoot) {
    const rest = normalizedRest(workdir.slice(2));
    normalizedWorkdir = `${separator}${separator}${rest}`;
  } else if (workdir.startsWith('/')) {
    const rest = normalizedRest(workdir.slice(1));
    normalizedWorkdir = rest ? `/${rest}` : '/';
  } else {
    normalizedWorkdir = normalizedRest(workdir);
  }

  const normalizedPath = operationPath.replace(/[\\/]+/g, separator).replace(/^[\\/]+/, '');
  if (!normalizedWorkdir || normalizedWorkdir === separator) return `${separator}${normalizedPath}`;
  if (normalizedWorkdir.endsWith(separator)) return `${normalizedWorkdir}${normalizedPath}`;
  return `${normalizedWorkdir}${separator}${normalizedPath}`;
}

export function EditorFileTopBar({
  operationPath,
  imagePreview = false,
  imageDisplayName,
  imageDownloadHref,
}: EditorFileTopBarProps) {
  const { isMobile } = useMediaQuery();
  const currentSession = useCurrentSession();
  const downloadFile = useEditorStore((s) => s.downloadFile);
  const requestSave = useEditorStore((s) => s.requestSave);
  const isDirty = useEditorStore((s) => s.dirty.has(operationPath));
  const requestChatAttachment = useUIStore((s) => s.requestChatAttachment);
  const showToast = useUIStore((s) => s.showToast);
  const navigate = useNavigate();
  const [copied, setCopied] = useState(false);
  const resetCopiedRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const displayPath = imageDisplayName || getDisplayPath(currentSession?.workdir, operationPath);
  const copyKey = `${currentSession?.id ?? ''}\u0000${currentSession?.workdir ?? ''}\u0000${operationPath}`;
  const copyGenerationRef = useRef(0);
  const copyKeyRef = useRef(copyKey);
  // Invalidate pending copy callbacks during render so a promise resolving
  // before the dependency effect runs cannot update the next file.
  if (copyKeyRef.current !== copyKey) {
    copyKeyRef.current = copyKey;
    copyGenerationRef.current += 1;
  }
  const copyLabel = currentSession?.workdir ? '复制完整路径' : '复制文件路径';
  const copiedLabel = currentSession?.workdir ? '完整路径已复制' : '文件路径已复制';

  useEffect(() => {
    setCopied(false);
    if (resetCopiedRef.current) {
      clearTimeout(resetCopiedRef.current);
      resetCopiedRef.current = null;
    }
    return () => {
      copyGenerationRef.current += 1;
      if (resetCopiedRef.current) {
        clearTimeout(resetCopiedRef.current);
        resetCopiedRef.current = null;
      }
    };
  }, [copyKey]);

  const handleCopy = async () => {
    const copyGeneration = copyGenerationRef.current;
    const copyKeyAtStart = copyKey;
    try {
      await copyText(displayPath);
      if (copyGenerationRef.current !== copyGeneration || copyKeyRef.current !== copyKeyAtStart)
        return;
      setCopied(true);
      showToast(`${currentSession?.workdir ? '完整路径' : '文件路径'}已复制`);
      if (resetCopiedRef.current) clearTimeout(resetCopiedRef.current);
      resetCopiedRef.current = setTimeout(() => {
        if (copyGenerationRef.current !== copyGeneration || copyKeyRef.current !== copyKeyAtStart)
          return;
        setCopied(false);
        resetCopiedRef.current = null;
      }, 1600);
    } catch {
      if (copyGenerationRef.current !== copyGeneration || copyKeyRef.current !== copyKeyAtStart)
        return;
      setCopied(false);
      showToast('复制路径失败', 'error');
    }
  };

  const handleAddToChat = () => {
    if (!currentSession?.id) {
      showToast('当前没有可用的 session', 'error');
      return;
    }
    requestChatAttachment(currentSession.id, operationPath);
    showToast('文件已加入聊天附件');
    navigate('/');
  };

  const handleDownload = () => {
    if (!imageDownloadHref) {
      downloadFile(operationPath);
      return;
    }
    const link = document.createElement('a');
    link.href = imageDownloadHref;
    link.download = '';
    link.rel = 'noopener';
    document.body.appendChild(link);
    link.click();
    link.remove();
  };

  return (
    <div
      data-testid="editor-file-topbar"
      className="flex min-h-8 items-center gap-2 border-b border-border-default bg-bg-primary px-2 py-1"
    >
      <span
        className="min-w-0 flex-1 truncate font-mono text-[11px] text-text-secondary"
        title={displayPath}
      >
        {displayPath}
      </span>
      <button
        type="button"
        aria-label="保存文件"
        title={isDirty ? '保存文件' : '文件没有未保存修改'}
        disabled={!isDirty}
        onClick={() => requestSave(operationPath)}
        className="flex h-7 shrink-0 items-center gap-1 rounded px-1.5 text-text-tertiary hover:bg-bg-tertiary hover:text-text-primary disabled:cursor-not-allowed disabled:opacity-40"
      >
        <SaveIcon size={14} />
        <span className="hidden sm:inline text-[11px]">保存</span>
      </button>
      <button
        type="button"
        aria-label={copied ? copiedLabel : copyLabel}
        title={copied ? copiedLabel : copyLabel}
        onClick={() => void handleCopy()}
        className="flex h-7 w-7 shrink-0 items-center justify-center rounded text-text-tertiary hover:bg-bg-tertiary hover:text-text-primary"
      >
        {copied ? <Check size={14} /> : <Copy size={14} />}
      </button>
      {(isMobile || imagePreview) && (
        <>
          <button
            type="button"
            aria-label="下载当前文件"
            title="下载当前文件"
            onClick={handleDownload}
            className="flex h-7 w-7 shrink-0 items-center justify-center rounded text-text-tertiary hover:bg-bg-tertiary hover:text-text-primary"
          >
            <Download size={14} />
          </button>
          {!imageDownloadHref && <button
            type="button"
            aria-label="加入聊天"
            title="加入聊天"
            onClick={handleAddToChat}
            className="flex h-7 w-7 shrink-0 items-center justify-center rounded text-text-tertiary hover:bg-bg-tertiary hover:text-text-primary"
          >
            <MessageSquare size={14} />
          </button>}
        </>
      )}
    </div>
  );
}

