// ── Schedule entry draft（schedule 是列表，每条 entry 独立编辑） ──

export interface ScheduleEntryDraft {
  key: string;
  kind: ScheduleEntryKind;
  mode: ScheduleMode;
  /** `datetime-local` value (no seconds) for kind=once. */
  at: string;
  intervalSec: number;
  cron: string;
  timezone: string;
  misfirePolicy: MisfirePolicy;
  enabled: boolean;
  graceSec: number | null;
}

export function newEntryDraft(): ScheduleEntryDraft {
  const soon = new Date(Date.now() + 3600_000);
  soon.setSeconds(0, 0);
  return {
    key: Math.random().toString(36).slice(2),
    kind: 'cron',
    mode: 'simple',
    at: toLocalInput(soon),
    intervalSec: 3600,
    cron: simpleToCron(DEFAULT_SIMPLE),
    timezone: DEFAULT_TIMEZONE,
    misfirePolicy: 'fire_now',
    enabled: true,
    graceSec: null,
  };
}

/** 反向：把已有 ScheduleEntry 还原为编辑态 draft（供 Edit 表单预填）。 */
export function scheduleEntryToDraft(entry: ScheduleEntry): ScheduleEntryDraft {
  const simpleSpec =
    entry.kind === 'cron' ? parseSimpleSchedule({ kind: 'cron', cron: entry.cron ?? '' }) : null;
  const soon = new Date(Date.now() + 3600_000);
  soon.setSeconds(0, 0);
  return {
    key: entry.id,
    kind: entry.kind,
    mode: entry.kind === 'cron' && simpleSpec ? 'simple' : 'advanced',
    at: entry.at ? entry.at.slice(0, 16) : toLocalInput(soon),
    intervalSec: entry.intervalSec ?? 3600,
    cron: entry.cron ?? simpleToCron(DEFAULT_SIMPLE),
    timezone: entry.timezone ?? DEFAULT_TIMEZONE,
    misfirePolicy: entry.misfirePolicy,
    enabled: entry.enabled,
    graceSec: entry.graceSec ?? null,
  };
}

/** 编辑态 draft → 服务端 schedule spec（POST/PATCH 提交用；控制键由服务端定）。 */
export function buildScheduleSpec(d: ScheduleEntryDraft): JobScheduleSpec {
  const timezone = d.timezone.trim() || DEFAULT_TIMEZONE;
  if (d.kind === 'once') {
    return {
      kind: 'once',
      at: d.at ? `${d.at}:00` : null,
      timezone,
      misfirePolicy: d.misfirePolicy,
      enabled: d.enabled,
      ...(d.graceSec != null ? { graceSec: d.graceSec } : {}),
    };
  }
  if (d.kind === 'interval') {
    return {
      kind: 'interval',
      intervalSec: Math.max(1, Math.round(d.intervalSec)),
      timezone,
      misfirePolicy: d.misfirePolicy,
      enabled: d.enabled,
      ...(d.graceSec != null ? { graceSec: d.graceSec } : {}),
    };
  }
  return {
    kind: 'cron',
    cron: d.cron.trim(),
    timezone,
    misfirePolicy: d.misfirePolicy,
    enabled: d.enabled,
    ...(d.graceSec != null ? { graceSec: d.graceSec } : {}),
  };
}

/** 服务端 entry → spec（整体替换 schedule 时回传，保留 enabled/misfire 覆盖）。 */
export function entryToSpec(entry: ScheduleEntry): JobScheduleSpec {
  const spec: JobScheduleSpec = {
    kind: entry.kind,
    timezone: entry.timezone ?? undefined,
    misfirePolicy: entry.misfirePolicy,
    enabled: entry.enabled,
    graceSec: entry.graceSec,
  };
  if (entry.anchor) spec.anchor = entry.anchor;
  if (entry.kind === 'once') spec.at = entry.at ?? null;
  else if (entry.kind === 'interval') spec.intervalSec = entry.intervalSec ?? entry.interval_sec ?? null;
  else spec.cron = entry.cron ?? null;
  return spec;
}

function ScheduleEntryEditor({
  entry,
  index,
  canRemove,
  onChange,
  onRemove,
}: {
  entry: ScheduleEntryDraft;
  index: number;
  canRemove: boolean;
  onChange: (e: ScheduleEntryDraft) => void;
  onRemove: () => void;
}) {
  const simpleSpec = useMemo(
    () =>
      parseSimpleSchedule({
        kind: entry.kind,
        intervalSec: entry.kind === 'interval' ? entry.intervalSec : null,
        cron: entry.kind === 'cron' ? entry.cron : null,
      }),
    [entry.kind, entry.intervalSec, entry.cron],
  );

  const preview = useMemo(() => {
    if (entry.kind === 'once') return entry.at ? [`${entry.at}:00`] : [];
    if (entry.kind === 'interval') {
      const sec = Math.max(1, Math.round(entry.intervalSec));
      return [toNaiveIso(new Date(Date.now() + sec * 1000))];
    }
    return nextCronFires(entry.cron.trim(), PREVIEW_COUNT);
  }, [entry.kind, entry.at, entry.intervalSec, entry.cron]);

  const applySimple = (patch: Partial<SimpleSpec>) => {
    const next = { ...(simpleSpec ?? DEFAULT_SIMPLE), ...patch };
    onChange({ ...entry, kind: 'cron', cron: simpleToCron(next) });
  };

  const switchMode = (mode: ScheduleMode) => {
    if (mode === entry.mode) return;
    if (mode === 'simple') {
      const spec = simpleSpec ?? DEFAULT_SIMPLE;
      onChange({ ...entry, mode, kind: 'cron', cron: simpleToCron(spec) });
    } else {
      onChange({ ...entry, mode });
    }
  };

  const toggleWeekday = (iso: number) => {
    if (!simpleSpec) return;
    const has = simpleSpec.weekdays.includes(iso);
    const weekdays = has
      ? simpleSpec.weekdays.filter((w) => w !== iso)
      : [...simpleSpec.weekdays, iso].sort((a, b) => a - b);
    applySimple({ weekdays });
  };

  return (
    <div className="flex flex-col gap-2 rounded border border-border-default bg-bg-primary p-2.5">
      <div className="flex items-center justify-between gap-2">
        <div className="flex items-center gap-2">
          <MiniSwitch
            label={`Schedule ${index + 1} enabled`}
            checked={entry.enabled}
            onChange={(v) => onChange({ ...entry, enabled: v })}
          />
          <span className="text-xs font-medium text-text-primary">Schedule {index + 1}</span>
        </div>
        <button
          type="button"
          onClick={onRemove}
          disabled={!canRemove}
          aria-label="Remove schedule entry"
          title="Remove schedule entry"
          className="rounded border border-transparent p-1 text-text-tertiary transition-colors hover:bg-bg-hover hover:text-danger disabled:opacity-40 disabled:pointer-events-none"
        >
          <Trash2 size={14} />
        </button>
      </div>

      <div className="flex items-center justify-between gap-2">
        <span className="text-[11px] text-text-tertiary">Mode</span>
        <div className="flex gap-1">
          {SCHEDULE_MODES.map((m) => (
            <button
              key={m.mode}
              type="button"
              aria-pressed={entry.mode === m.mode}
              disabled={m.mode === 'simple' && !simpleSpec}
              title={m.mode === 'simple' && !simpleSpec ? '当前 cron 无法用简单模式表达' : m.title}
              onClick={() => switchMode(m.mode)}
              className={`rounded border px-2 py-0.5 text-[10px] font-medium transition-colors disabled:opacity-50 disabled:pointer-events-none ${
                entry.mode === m.mode
                  ? 'border-accent/50 bg-accent/10 text-accent'
                  : 'border-border-default bg-bg-tertiary text-text-secondary hover:bg-bg-hover hover:text-text-primary'
              }`}
            >
              {m.label}
            </button>
          ))}
        </div>
      </div>

      {entry.mode === 'simple' && simpleSpec && (
        <div className="flex flex-col gap-2">
          <Field label="重复频率">
            <select
              aria-label="Frequency"
              value={simpleSpec.freq}
              onChange={(e) => applySimple({ freq: e.target.value as SimpleFreq })}
              className={inputClass}
            >
              {SIMPLE_FREQS.map((f) => (
                <option key={f.freq} value={f.freq}>
                  {f.label}
                </option>
              ))}
            </select>
          </Field>

          {(simpleSpec.freq === 'minutes' || simpleSpec.freq === 'hours') && (
            <div className="flex flex-col gap-1">
              <span className="text-[11px] text-text-tertiary">
                {simpleSpec.freq === 'minutes' ? '间隔分钟数 (1-59)' : '间隔小时数 (1-23)'}
              </span>
              <input
                aria-label={simpleSpec.freq === 'minutes' ? 'Every N minutes' : 'Every N hours'}
                type="number"
                min={simpleSpec.freq === 'minutes' ? MINUTES_RANGE.min : HOURS_RANGE.min}
                max={simpleSpec.freq === 'minutes' ? MINUTES_RANGE.max : HOURS_RANGE.max}
                value={simpleSpec.n}
                onChange={(e) => applySimple({ n: Number(e.target.value) })}
                className={inputClass}
              />
              <div className="flex flex-wrap gap-1">
                {(simpleSpec.freq === 'minutes' ? MINUTE_PRESETS : HOUR_PRESETS).map((n) => (
                  <button
                    key={n}
                    type="button"
                    onClick={() => applySimple({ n })}
                    className="rounded border border-border-default bg-bg-tertiary px-1.5 py-0.5 text-[10px] text-text-secondary transition-colors hover:bg-bg-hover hover:text-text-primary"
                  >
                    {n}
                    {simpleSpec.freq === 'minutes' ? ' 分钟' : ' 小时'}
                  </button>
                ))}
              </div>
            </div>
          )}

          {simpleSpec.freq === 'weekly' && (
            <div className="flex flex-col gap-1">
              <span className="text-[11px] text-text-tertiary">星期（可多选）</span>
              <div className="flex flex-wrap gap-1">
                {WEEKDAYS.map((w) => {
                  const active = simpleSpec.weekdays.includes(w.iso);
                  return (
                    <button
                      key={w.iso}
                      type="button"
                      aria-label={`星期${w.label}`}
                      aria-pressed={active}
                      onClick={() => toggleWeekday(w.iso)}
                      className={`w-8 rounded border px-1 py-0.5 text-[11px] transition-colors ${
                        active
                          ? 'border-accent/50 bg-accent/10 text-accent'
                          : 'border-border-default bg-bg-tertiary text-text-secondary hover:bg-bg-hover hover:text-text-primary'
                      }`}
                    >
                      {w.label}
                    </button>
                  );
                })}
              </div>
            </div>
          )}

          {simpleSpec.freq === 'monthly' && (
            <Field label="每月几号 (1-31)">
              <input
                aria-label="Day of month"
                type="number"
                min={MONTH_DAY_RANGE.min}
                max={MONTH_DAY_RANGE.max}
                value={simpleSpec.day}
                onChange={(e) => applySimple({ day: Number(e.target.value) })}
                className={inputClass}
              />
            </Field>
          )}

          {simpleSpec.freq !== 'minutes' && simpleSpec.freq !== 'hours' && (
            <Field label="触发时间">
              <input
                aria-label="Fire time"
                type="time"
                value={simpleSpec.time}
                onChange={(e) => applySimple({ time: e.target.value })}
                className={inputClass}
              />
            </Field>
          )}

          <div className="text-[11px] text-text-tertiary">
            cron: <code className="font-mono text-text-secondary">{simpleToCron(simpleSpec)}</code>
          </div>
        </div>
      )}

      {entry.mode === 'simple' && !simpleSpec && (
        <div className="rounded border border-border-muted bg-bg-tertiary px-2.5 py-2 text-[11px] text-text-tertiary">
          当前 cron 无法用简单模式表达，请切换到高级模式编辑（原始表达式已保留）。
        </div>
      )}

      {entry.mode === 'advanced' && (
        <>
          <div className="flex gap-1">
            {KINDS.map((k) => (
              <button
                key={k.kind}
                type="button"
                onClick={() => onChange({ ...entry, kind: k.kind })}
                aria-pressed={entry.kind === k.kind}
                className={`flex-1 rounded border px-2 py-1 text-[11px] font-medium transition-colors ${
                  entry.kind === k.kind
                    ? 'border-accent/50 bg-accent/10 text-accent'
                    : 'border-border-default bg-bg-tertiary text-text-secondary hover:bg-bg-hover hover:text-text-primary'
                }`}
              >
                {k.label}
                <span className="ml-1 text-[10px] opacity-70">{k.hint}</span>
              </button>
            ))}
          </div>

          {entry.kind === 'once' && (
            <Field label="Fire at">
              <input
                aria-label="Fire at"
                type="datetime-local"
                value={entry.at}
                onChange={(e) => onChange({ ...entry, at: e.target.value })}
                className={inputClass}
              />
            </Field>
          )}

          {entry.kind === 'interval' && (
            <div className="flex flex-col gap-1">
              <span className="text-[11px] text-text-tertiary">Interval (seconds)</span>
              <input
                aria-label="Interval seconds"
                type="number"
                min={1}
                value={entry.intervalSec}
                onChange={(e) => onChange({ ...entry, intervalSec: Number(e.target.value) })}
                className={inputClass}
              />
              <div className="flex flex-wrap gap-1">
                {INTERVAL_PRESETS.map((p) => (
                  <button
                    key={p.sec}
                    type="button"
                    onClick={() => onChange({ ...entry, intervalSec: p.sec })}
                    className="rounded border border-border-default bg-bg-tertiary px-1.5 py-0.5 text-[10px] text-text-secondary transition-colors hover:bg-bg-hover hover:text-text-primary"
                  >
                    {p.label}
                  </button>
                ))}
              </div>
            </div>
          )}

          {entry.kind === 'cron' && (
            <div className="flex flex-col gap-1">
              <span className="text-[11px] text-text-tertiary">Cron (min hour dom month dow)</span>
              <input
                aria-label="Cron expression"
                value={entry.cron}
                onChange={(e) => onChange({ ...entry, cron: e.target.value })}
                placeholder="0 9 * * 1-5"
                className={`${inputClass} font-mono`}
              />
              <div className="flex flex-wrap gap-1">
                {CRON_PRESETS.map((p) => (
                  <button
                    key={p.expr}
                    type="button"
                    onClick={() => onChange({ ...entry, cron: p.expr })}
                    title={p.expr}
                    className="rounded border border-border-default bg-bg-tertiary px-1.5 py-0.5 text-[10px] text-text-secondary transition-colors hover:bg-bg-hover hover:text-text-primary"
                  >
                    {p.label}
                  </button>
                ))}
              </div>
            </div>
          )}
        </>
      )}

      <div className="flex flex-wrap gap-2">
        <Field label="Missed fire">
          <select
            aria-label="Missed fire"
            value={entry.misfirePolicy}
            onChange={(e) => onChange({ ...entry, misfirePolicy: e.target.value as MisfirePolicy })}
            className={inputClass}
          >
            {MISFIRE_POLICIES.map((p) => (
              <option key={p.value} value={p.value}>
                {p.label}
              </option>
            ))}
          </select>
        </Field>
        <Field label="Timezone">
          <input
            aria-label="Timezone"
            value={entry.timezone}
            onChange={(e) => onChange({ ...entry, timezone: e.target.value })}
            placeholder={DEFAULT_TIMEZONE}
            className={inputClass}
          />
        </Field>
        <Field label="Misfire grace (seconds; blank uses default)">
          <input
            aria-label="Misfire grace seconds"
            type="number"
            min={0}
            max={86400}
            value={entry.graceSec ?? ''}
            onChange={(e) => onChange({
              ...entry,
              graceSec: e.target.value === '' ? null : Number(e.target.value),
            })}
            className={inputClass}
          />
        </Field>
      </div>

      <div className="flex flex-wrap items-baseline gap-x-2 gap-y-0.5 text-[11px]">
        <span className="text-text-tertiary">Next {preview.length} fires</span>
        {preview.length === 0 && <span className="text-text-tertiary">—</span>}
        {preview.map((t, i) => (
          <span key={`${t}-${i}`} className="font-mono text-text-secondary">
            {formatDateTime(t)}
          </span>
        ))}
      </div>
    </div>
  );
}

export function ScheduleListEditor({
  entries,
  onChange,
}: {
  entries: ScheduleEntryDraft[];
  onChange: (entries: ScheduleEntryDraft[]) => void;
}) {
  const updateEntry = (key: string, next: ScheduleEntryDraft) =>
    onChange(entries.map((e) => (e.key === key ? next : e)));
  const removeEntry = (key: string) =>
    onChange(entries.length > 1 ? entries.filter((e) => e.key !== key) : entries);
  const addEntry = () => onChange([...entries, newEntryDraft()]);

  return (
    <div className="flex flex-col gap-2">
      <div className="flex items-center justify-between gap-2">
        <span className="text-[11px] text-text-tertiary">Schedule（可多条）</span>
        <button
          type="button"
          onClick={addEntry}
          className="inline-flex items-center gap-1 rounded border border-border-default bg-bg-tertiary px-2 py-0.5 text-[11px] text-text-secondary transition-colors hover:bg-bg-hover hover:text-text-primary"
        >
          <Plus size={12} />
          Add entry
        </button>
      </div>
      {entries.map((e, i) => (
        <ScheduleEntryEditor
          key={e.key}
          entry={e}
          index={i}
          canRemove={entries.length > 1}
          onChange={(next) => updateEntry(e.key, next)}
          onRemove={() => removeEntry(e.key)}
        />
      ))}
    </div>
  );
}

import { useEffect, useRef, useState } from 'react';
import { isMockMode } from '@/demo/mockBackend';
import {
  claimStartupRecovery,
  decideStartupRecovery,
  fetchStartupRecovery,
} from '@/services/api';
import { useSessionStore } from '@/stores/sessionStore';
import { useWorkerStore } from '@/stores/workerStore';
import type {
  ApiStartupRecoveryChoice,
  ApiStartupRecoveryRecord,
} from '@/types';

const CHOICES: Array<{
  value: ApiStartupRecoveryChoice;
  title: string;
  detail: string;
}> = [
  {
    value: 'restart',
    title: 'Restart these Sessions',
    detail: 'Send “继续” to each candidate through the normal Session broadcast path.',
  },
  {
    value: 'preserve-running',
    title: 'Keep their legal state as running',
    detail: 'Do not restart them and leave their persisted legal state unchanged.',
  },
  {
    value: 'sync-actual',
    title: 'Update legal state to current Worker state',
    detail: 'Do not restart them; Pan will read each current runtime state and persist it.',
  },
];

function makeTabId(): string {
  return globalThis.crypto?.randomUUID?.()
    ?? `tab-${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
}

/**
 * Converge the Session list after a recovery decision completes.
 *
 * Legal-state writes (`sync-actual`, the durable preserve/restart outcomes)
 * are deliberately silent on the WebSocket — the Session list learns about
 * them exclusively through the HTTP snapshot. `restart` converges on its own
 * through worker spawn/status events, but the other choices fire no event at
 * all, so without this refresh the sidebar keeps the pre-decision snapshot
 * and a Session whose legal state was just synchronized to the (idle) runtime
 * keeps rendering the legal-running mismatch indicator indefinitely.
 */
export function convergeAfterStartupRecovery(): void {
  void useSessionStore.getState().loadSessions();
  void useWorkerStore.getState().refresh();
}

export function StartupRecoveryPrompt() {
  const tabId = useRef(makeTabId());
  const [record, setRecord] = useState<ApiStartupRecoveryRecord | null>(null);
  const [claimed, setClaimed] = useState(false);
  const [selected, setSelected] = useState<ApiStartupRecoveryChoice | null>(null);
  const [busy, setBusy] = useState(false);
  const [loadError, setLoadError] = useState<string | null>(null);
  // A decision can complete through this tab's submit, another tab, or the
  // automatic startup preference. Converge exactly once per mount when the
  // record is first observed as completed, so the sidebar cannot keep a stale
  // legal-running red (or a stale running status) from before the decision.
  const convergedRef = useRef(false);

  useEffect(() => {
    if (isMockMode()) return;
    let active = true;
    let loading = false;
    const refresh = async () => {
      if (loading) return;
      loading = true;
      try {
        const status = await fetchStartupRecovery();
        if (!active) return;
        setRecord(status);
        if (status.state === 'no_candidates' || status.state === 'completed') {
          if (status.state === 'completed' && !convergedRef.current) {
            convergedRef.current = true;
            convergeAfterStartupRecovery();
          }
          setClaimed(false);
          setLoadError(null);
          return;
        }
        if (status.state === 'initializing') return;
        const claim = await claimStartupRecovery(status.generation, tabId.current);
        if (!active) return;
        setClaimed(claim.claimed);
        setRecord((current) => ({
          ...(current ?? status),
          state: claim.state,
          decision: claim.decision ?? status.decision,
          attempts: claim.attempts ?? status.attempts,
          results: claim.results ?? status.results,
          error: claim.error ?? status.error,
          candidateSnapshot: claim.candidates ?? status.candidateSnapshot,
        }));
        // The claim can observe another tab's (or the automatic preference's)
        // completed decision; the convergence requirement is identical.
        if (claim.state === 'completed' && !convergedRef.current) {
          convergedRef.current = true;
          convergeAfterStartupRecovery();
        }
        if (claim.decision) setSelected(claim.decision);
        setLoadError(null);
      } catch (error) {
        if (active) setLoadError(error instanceof Error ? error.message : String(error));
      } finally {
        loading = false;
      }
    };
    void refresh();
    const timer = window.setInterval(() => void refresh(), 5000);
    return () => {
      active = false;
      window.clearInterval(timer);
    };
  }, []);

  const submit = async () => {
    if (!record || !selected || busy) return;
    setBusy(true);
    setLoadError(null);
    try {
      const next = await decideStartupRecovery(record.generation, tabId.current, selected);
      setRecord(next);
      if (next.state === 'completed') {
        if (!convergedRef.current) convergedRef.current = true;
        convergeAfterStartupRecovery();
      }
      if (next.state === 'failed') setLoadError(next.error || 'Startup recovery failed.');
    } catch (error) {
      setLoadError(error instanceof Error ? error.message : String(error));
      try {
        const latest = await fetchStartupRecovery();
        if (latest.generation === record.generation) {
          setRecord(latest);
          if (latest.decision) setSelected(latest.decision);
        }
      } catch {
        // Keep the original error visible; the lease heartbeat retries status.
      }
    } finally {
      setBusy(false);
    }
  };

  if (!claimed || !record || !record.candidateSnapshot.length
      || record.state === 'completed' || record.state === 'no_candidates') {
    if (!loadError || record || claimed) return null;
    return (
      <div className="fixed inset-0 z-[100] grid place-items-center bg-black/55 px-4">
        <section className="w-full min-w-0 max-w-[32rem] rounded-lg border border-border-default bg-bg-secondary p-5 shadow-2xl">
          <h2 className="text-base font-semibold text-text-primary">Session recovery decision</h2>
          <p className="mt-2 text-sm text-text-secondary">{loadError}</p>
          <button
            type="button"
            onClick={() => window.location.reload()}
            className="mt-4 rounded bg-accent px-3 py-2 text-xs text-white"
          >
            Retry dashboard load
          </button>
        </section>
      </div>
    );
  }

  const lockedChoice = record.decision;
  const processing = busy || record.state === 'processing';
  const failedResults = record.results.filter((result) =>
    result.status !== 'queued' && result.status !== 'preserved' && result.status !== 'updated',
  );
  return (
    <div className="fixed inset-0 z-[100] grid place-items-center bg-black/55 px-4">
      <section
        role="dialog"
        aria-modal="true"
        aria-labelledby="startup-recovery-title"
        className="w-full min-w-0 max-w-[36rem] rounded-lg border border-border-default bg-bg-secondary p-5 shadow-2xl"
      >
        <h2 id="startup-recovery-title" className="text-base font-semibold text-text-primary">
          Continue previous Sessions?
        </h2>
        <p className="mt-2 text-sm text-text-secondary">
          Pan found {record.candidateSnapshot.length} Session(s) whose persisted legal state is running
          and which currently have no live Worker.
        </p>
        <ul className="mt-3 max-h-32 space-y-1 overflow-y-auto rounded border border-border-muted bg-bg-primary px-3 py-2 text-xs text-text-secondary">
          {record.candidateSnapshot.map((candidate) => (
            <li key={candidate.id} className="truncate" title={candidate.id}>
              {candidate.name || candidate.id}
            </li>
          ))}
        </ul>
        <fieldset className="mt-4 space-y-2">
          <legend className="sr-only">Choose startup recovery action</legend>
          {CHOICES.map((choice, index) => {
            const disabledByRecordedChoice = Boolean(lockedChoice && lockedChoice !== choice.value);
            return (
              <label
                key={choice.value}
                className={`flex cursor-pointer items-start gap-3 rounded-md border px-3 py-2.5 ${
                  selected === choice.value
                    ? 'border-accent bg-accent/10'
                    : 'border-border-muted bg-bg-primary'
                } ${disabledByRecordedChoice || processing ? 'opacity-60' : ''}`}
              >
                <input
                  type="radio"
                  name="startup-recovery-choice"
                  checked={selected === choice.value}
                  disabled={disabledByRecordedChoice || processing}
                  onChange={() => setSelected(choice.value)}
                  className="mt-0.5"
                />
                <span>
                  <span className="block text-xs font-medium text-text-primary">
                    {index + 1}. {choice.title}
                  </span>
                  <span className="mt-0.5 block text-[11px] text-text-tertiary">
                    {choice.detail}
                  </span>
                </span>
              </label>
            );
          })}
        </fieldset>
        {loadError && (
          <p role="alert" className="mt-3 rounded border border-danger/30 bg-danger/10 px-3 py-2 text-xs text-danger">
            {loadError}
          </p>
        )}
        {failedResults.length > 0 && (
          <ul className="mt-2 space-y-1 text-[10px] text-danger">
            {failedResults.map((result, index) => (
              <li key={`${String(result.sessionId ?? 'session')}-${index}`}>
                {String(result.sessionId ?? 'Session')}: {String(result.error ?? result.result ?? result.status ?? 'failed')}
              </li>
            ))}
          </ul>
        )}
        <div className="mt-4 flex items-center justify-between gap-3">
          <span className="text-[10px] text-text-tertiary">
            {processing ? 'Applying saved choice…' : lockedChoice ? 'Retry is limited to the saved choice.' : 'Choose one action to continue.'}
          </span>
          <button
            type="button"
            disabled={!selected || processing || Boolean(lockedChoice && selected !== lockedChoice)}
            onClick={() => void submit()}
            className="shrink-0 rounded bg-accent px-4 py-2 text-xs font-medium text-white disabled:cursor-not-allowed disabled:opacity-50"
          >
            {processing ? 'Working…' : record.state === 'failed' ? 'Retry choice' : 'Continue'}
          </button>
        </div>
      </section>
    </div>
  );
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Modal } from '@/components/ui/Modal';
import { Button } from '@/components/ui/Button';
import { getAvailableCliAdapters, useAdapterStore } from '@/stores/adapterStore';
import { useSessionStore } from '@/stores/sessionStore';
import { useUIStore } from '@/stores/uiStore';
import { getCreationWorkspaceIds } from '@/utils/creationWorkspace';
import type {
  CbcProject,
  CbcSessionItem,
  KimiWorkspace,
  KimiSessionItem,
  OpencodeSessionItem,
  CodexSessionItem,
} from '@/types';
import {
  fetchCbcProjects,
  fetchCbcSessions,
  importCbcSession,
  fetchKimiWorkspaces,
  fetchKimiSessions,
  importKimiSession,
  fetchOpencodeSessions,
  importOpencodeSession,
  fetchCodexSessions,
  importCodexSession,
} from '@/services/api';

interface ImportModalProps {
  open: boolean;
  onClose: () => void;
  initialAdapter?: Adapter;
}

type Adapter = 'cbc' | 'kimi' | 'opencode' | 'codex';

const IMPORT_ADAPTERS: Array<{ name: Adapter; label: string }> = [
  { name: 'cbc', label: 'cbc' },
  { name: 'kimi', label: 'kimi' },
  { name: 'opencode', label: 'opencode' },
  { name: 'codex', label: 'codex' },
];

function formatTime(ts: string): string {
  try {
    const d = new Date(ts);
    return d.toLocaleString(undefined, {
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  } catch {
    return ts;
  }
}

export function ImportModal({ open, onClose, initialAdapter = 'cbc' }: ImportModalProps) {
  const loadSessions = useSessionStore((s) => s.loadSessions);
  const selectSession = useSessionStore((s) => s.selectSession);
  const showToast = useUIStore((s) => s.showToast);
  const cliStatus = useAdapterStore((s) => s.cliStatus);
  const cliStatusLoading = useAdapterStore((s) => s.cliStatusLoading);
  const cliStatusError = useAdapterStore((s) => s.cliStatusError);
  const loadCliStatus = useAdapterStore((s) => s.loadCliStatus);

  const [adapter, setAdapter] = useState<Adapter | null>(null);

  // ── CBC state ──
  const [projects, setProjects] = useState<CbcProject[]>([]);
  const [projectsLoading, setProjectsLoading] = useState(false);
  const [selectedDrive, setSelectedDrive] = useState<string | null>(null);
  const [selectedProject, setSelectedProject] = useState<string | null>(null);
  const [cbcSessions, setCbcSessions] = useState<CbcSessionItem[]>([]);
  const [cbcLoading, setCbcLoading] = useState(false);

  // ── Kimi state ──
  const [workspaces, setWorkspaces] = useState<KimiWorkspace[]>([]);
  const [workspacesLoading, setWorkspacesLoading] = useState(false);
  const [selectedWorkspace, setSelectedWorkspace] = useState<string | null>(null);
  const [kimiSessions, setKimiSessions] = useState<KimiSessionItem[]>([]);
  const [kimiLoading, setKimiLoading] = useState(false);

  // ── OpenCode state ──
  const [opencodeCwd, setOpencodeCwd] = useState('');
  const [opencodeSessions, setOpencodeSessions] = useState<OpencodeSessionItem[]>([]);
  const [opencodeLoading, setOpencodeLoading] = useState(false);

  // ── Codex state ──
  const [codexCwd, setCodexCwd] = useState('');
  const [codexSessions, setCodexSessions] = useState<CodexSessionItem[]>([]);
  const [codexLoading, setCodexLoading] = useState(false);
  const codexRequest = useRef(0);

  // ── Import state ──
  const [importingId, setImportingId] = useState<string | null>(null);

  // ── Reset on open/close ──
  useEffect(() => {
    if (!open) return;
    loadCliStatus();
    setAdapter(null);
    setProjects([]);
    setProjectsLoading(false);
    setSelectedDrive(null);
    setSelectedProject(null);
    setCbcSessions([]);
    setCbcLoading(false);
    setWorkspaces([]);
    setWorkspacesLoading(false);
    setSelectedWorkspace(null);
    setKimiSessions([]);
    setKimiLoading(false);
    setOpencodeCwd('');
    setOpencodeSessions([]);
    setOpencodeLoading(false);
    setCodexCwd('');
    setCodexSessions([]);
    setCodexLoading(false);
    setImportingId(null);
  }, [open, loadCliStatus]);

  const availableCliAdapters = useMemo(
    () => getAvailableCliAdapters(cliStatus),
    [cliStatus],
  );
  const availableAdapterNames = useMemo(
    () => new Set(availableCliAdapters.map((item) => item.name)),
    [availableCliAdapters],
  );
  const availableImportAdapters = useMemo(
    () => IMPORT_ADAPTERS.filter((item) => availableAdapterNames.has(item.name)),
    [availableAdapterNames],
  );
  const initialAdapterUnavailable =
    !cliStatusLoading &&
    !!cliStatus &&
    !availableAdapterNames.has(initialAdapter);

  // Keep an explicitly requested tab when it is available; otherwise choose
  // the first supported available adapter. A null selection is intentional
  // for loading, error, and empty states so no import request can be issued.
  useEffect(() => {
    if (!open || cliStatusLoading || !cliStatus) return;
    setAdapter((current) => {
      if (current && availableAdapterNames.has(current)) return current;
      if (availableAdapterNames.has(initialAdapter)) return initialAdapter;
      return availableImportAdapters[0]?.name ?? null;
    });
  }, [
    open,
    cliStatusLoading,
    cliStatus,
    initialAdapter,
    availableAdapterNames,
    availableImportAdapters,
  ]);

  const handleAdapterChange = (next: Adapter) => {
    setAdapter(next);
    if (next === 'cbc') {
      setSelectedDrive(null);
      setSelectedProject(null);
      setCbcSessions([]);
    } else if (next === 'kimi') {
      setSelectedWorkspace(null);
      setKimiSessions([]);
    } else if (next === 'opencode') {
      setOpencodeSessions([]);
      setOpencodeLoading(false);
    } else if (next === 'codex') {
      setCodexSessions([]);
      setCodexLoading(false);
    }
  };

  // ── Load CBC projects ──
  useEffect(() => {
    if (!open || adapter !== 'cbc') return;
    setProjectsLoading(true);
    fetchCbcProjects()
      .then((list) => setProjects(list))
      .catch((e) => {
        showToast(
          e instanceof Error ? e.message : 'Failed to load projects',
          'error',
        );
      })
      .finally(() => setProjectsLoading(false));
  }, [open, adapter, showToast]);

  // ── Load CBC sessions when project changes ──
  useEffect(() => {
    if (!open || adapter !== 'cbc' || !selectedProject) return;
    setCbcLoading(true);
    setCbcSessions([]);
    fetchCbcSessions(selectedProject)
      .then((list) => setCbcSessions(list))
      .catch((e) => {
        showToast(
          e instanceof Error ? e.message : 'Failed to load sessions',
          'error',
        );
      })
      .finally(() => setCbcLoading(false));
  }, [open, adapter, selectedProject, showToast]);

  // ── Load Kimi workspaces ──
  useEffect(() => {
    if (!open || adapter !== 'kimi') return;
    setWorkspacesLoading(true);
    fetchKimiWorkspaces()
      .then((list) => setWorkspaces(list))
      .catch((e) => {
        showToast(
          e instanceof Error ? e.message : 'Failed to load workspaces',
          'error',
        );
      })
      .finally(() => setWorkspacesLoading(false));
  }, [open, adapter, showToast]);

  // ── Load Kimi sessions when workspace changes ──
  useEffect(() => {
    if (!open || adapter !== 'kimi' || !selectedWorkspace) return;
    setKimiLoading(true);
    setKimiSessions([]);
    fetchKimiSessions(selectedWorkspace)
      .then((list) => setKimiSessions(list))
      .catch((e) => {
        showToast(
          e instanceof Error ? e.message : 'Failed to load sessions',
          'error',
        );
      })
      .finally(() => setKimiLoading(false));
  }, [open, adapter, selectedWorkspace, showToast]);

  // ── Load OpenCode sessions (filtered by optional cwd) ──
  const loadOpencode = useCallback(
    (cwd: string) => {
      setOpencodeLoading(true);
      fetchOpencodeSessions(cwd)
        .then((list) => setOpencodeSessions(list))
        .catch((e) => {
          showToast(
            e instanceof Error ? e.message : 'Failed to load opencode sessions',
            'error',
          );
        })
        .finally(() => setOpencodeLoading(false));
    },
    [showToast],
  );

  // Auto-load once when the opencode section opens (cwd=''). The "Load"
  // button re-triggers with the typed cwd; we intentionally don't depend on
  // opencodeCwd here so typing doesn't refetch on every keystroke.
  useEffect(() => {
    if (open && adapter === 'opencode') loadOpencode(opencodeCwd);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, adapter]);

  // ── Load Codex sessions (filtered by optional cwd) ──
  const loadCodex = useCallback(
    (cwd: string) => {
      const requestId = ++codexRequest.current;
      setCodexLoading(true);
      setCodexSessions([]);
      fetchCodexSessions(cwd)
        .then((list) => {
          if (requestId === codexRequest.current) setCodexSessions(list);
        })
        .catch((e) => {
          if (requestId !== codexRequest.current) return;
          showToast(
            e instanceof Error ? e.message : 'Failed to load Codex sessions',
            'error',
          );
        })
        .finally(() => {
          if (requestId === codexRequest.current) setCodexLoading(false);
        });
    },
    [showToast],
  );

  useEffect(() => {
    if (!open || adapter !== 'codex') return;
    setCodexSessions([]);
    setCodexLoading(true);
    const timer = setTimeout(() => loadCodex(codexCwd), 200);
    return () => {
      clearTimeout(timer);
      ++codexRequest.current;
    };
  }, [open, adapter, codexCwd, loadCodex]);

  // ── Import CBC session ──
  const handleImportCbc = async (item: CbcSessionItem) => {
    if (importingId) return;
    const activeWorkspaceId = useUIStore.getState().activeWorkspaceId;
    setImportingId(item.session_id);
    try {
      const workspaceIds = await getCreationWorkspaceIds(activeWorkspaceId);
      const result = await importCbcSession(item.session_id, item.project_dir, workspaceIds);
      onClose();
      await loadSessions();
      selectSession(result.id);
      showToast('Session imported');
    } catch (e) {
      showToast(
        e instanceof Error ? e.message : 'Import failed',
        'error',
      );
    } finally {
      setImportingId(null);
    }
  };

  // ── Import Kimi session ──
  const handleImportKimi = async (item: KimiSessionItem) => {
    if (importingId) return;
    const activeWorkspaceId = useUIStore.getState().activeWorkspaceId;
    setImportingId(item.session_id);
    try {
      const workspaceIds = await getCreationWorkspaceIds(activeWorkspaceId);
      const result = await importKimiSession(item.session_id, item.workDir, workspaceIds);
      onClose();
      await loadSessions();
      selectSession(result.id);
      showToast('Session imported');
    } catch (e) {
      showToast(
        e instanceof Error ? e.message : 'Import failed',
        'error',
      );
    } finally {
      setImportingId(null);
    }
  };

  // ── Import OpenCode session ──
  const handleImportOpencode = async (item: OpencodeSessionItem) => {
    if (importingId) return;
    const activeWorkspaceId = useUIStore.getState().activeWorkspaceId;
    setImportingId(item.session_id);
    try {
      const workspaceIds = await getCreationWorkspaceIds(activeWorkspaceId);
      const result = await importOpencodeSession(item.session_id, item.workDir, workspaceIds);
      onClose();
      await loadSessions();
      selectSession(result.id);
      showToast('Session imported');
    } catch (e) {
      showToast(
        e instanceof Error ? e.message : 'Import failed',
        'error',
      );
    } finally {
      setImportingId(null);
    }
  };

  // ── Import Codex session ──
  const handleImportCodex = async (item: CodexSessionItem) => {
    if (importingId) return;
    const activeWorkspaceId = useUIStore.getState().activeWorkspaceId;
    setImportingId(item.session_id);
    try {
      const workspaceIds = await getCreationWorkspaceIds(activeWorkspaceId);
      const result = await importCodexSession(item.session_id, item.workDir, workspaceIds);
      onClose();
      await loadSessions();
      selectSession(result.id);
      showToast('Session imported');
    } catch (e) {
      showToast(
        e instanceof Error ? e.message : 'Import failed',
        'error',
      );
    } finally {
      setImportingId(null);
    }
  };

  // ── CBC helpers ──
  const drives = [...new Set(projects.map((p) => p.drive))].sort();
  const filteredProjects = projects
    .filter((p) => !selectedDrive || p.drive === selectedDrive)
    .sort((a, b) => a.short_label.localeCompare(b.short_label));

  const driveSessionCount = (drive: string): number =>
    projects
      .filter((p) => p.drive === drive)
      .reduce((sum, p) => sum + p.session_count, 0);

  // ── Render ──
  const noImportAdapterMessage = cliStatus?.hasAvailable
    ? '当前没有可导入的可用 adapter。请安装对应 CLI 后重试。'
    : '当前没有可用的 Agent CLI。请安装对应 CLI 后重试。';

  return (
    <Modal open={open} onClose={onClose} title="Import Session" size="lg">
      <div className="flex flex-col gap-4">
        {/* Adapter tabs — only adapters marked available by /api/cli/status. */}
        {cliStatusLoading && (
          <div className="rounded border border-border-muted bg-bg-tertiary px-3 py-2 text-sm text-text-secondary">
            正在检测 Agent CLI 可用性…
          </div>
        )}
        {cliStatusError && (
          <div role="alert" className="rounded border border-danger/50 bg-danger/10 px-3 py-2 text-sm text-danger">
            无法检测 Agent CLI 可用性：{cliStatusError}。请检查 Pan 后端连接后重试。
          </div>
        )}
        {!cliStatusLoading && !cliStatusError && availableImportAdapters.length === 0 && (
          <div role="alert" className="rounded border border-warning/50 bg-warning/10 px-3 py-2 text-sm text-text-secondary">
            {noImportAdapterMessage}
          </div>
        )}
        {!cliStatusLoading && !cliStatusError && availableImportAdapters.length > 0 && (
          <div className="flex gap-1 rounded border border-border-muted bg-bg-tertiary p-0.5">
            {availableImportAdapters.map((item) => (
              <button
                key={item.name}
                type="button"
                onClick={() => handleAdapterChange(item.name)}
                className={`flex-1 rounded px-3 py-1 text-xs font-medium transition-colors ${
                  adapter === item.name
                    ? 'bg-accent text-white'
                    : 'text-text-secondary hover:text-text-primary'
                }`}
              >
                {item.label}
              </button>
            ))}
          </div>
        )}

        {initialAdapterUnavailable && availableImportAdapters.length > 0 && (
          <p className="-mt-2 text-xs text-text-secondary">
            请求的 adapter <code>{initialAdapter}</code> 当前不可用，已切换到可用的 <code>{adapter}</code>。
          </p>
        )}

        {adapter && availableImportAdapters.some((item) => item.name === adapter) && (
          <hr className="border-border-muted" />
        )}

        {/* cbc import */}
        {adapter === 'cbc' && (
          <CbcSection
            projectsLoading={projectsLoading}
            drives={drives}
            selectedDrive={selectedDrive}
            onDriveChange={(d) => {
              setSelectedDrive(d);
              setSelectedProject(null);
              setCbcSessions([]);
            }}
            driveSessionCount={driveSessionCount}
            filteredProjects={filteredProjects}
            selectedProject={selectedProject}
            onProjectChange={(p) => setSelectedProject(p)}
            cbcSessions={cbcSessions}
            cbcLoading={cbcLoading}
            importingId={importingId}
            onImport={handleImportCbc}
          />
        )}

        {/* kimi import */}
        {adapter === 'kimi' && (
          <KimiSection
            workspacesLoading={workspacesLoading}
            workspaces={workspaces}
            selectedWorkspace={selectedWorkspace}
            onWorkspaceChange={(w) => {
              setSelectedWorkspace(w);
              setKimiSessions([]);
            }}
            kimiSessions={kimiSessions}
            kimiLoading={kimiLoading}
            importingId={importingId}
            onImport={handleImportKimi}
          />
        )}

        {/* opencode import */}
        {adapter === 'opencode' && (
          <OpencodeSection
            cwd={opencodeCwd}
            onCwdChange={setOpencodeCwd}
            sessions={opencodeSessions}
            loading={opencodeLoading}
            importingId={importingId}
            onLoad={() => loadOpencode(opencodeCwd)}
            onImport={handleImportOpencode}
          />
        )}

        {/* codex import */}
        {adapter === 'codex' && (
          <CodexSection
            cwd={codexCwd}
            onCwdChange={setCodexCwd}
            sessions={codexSessions}
            loading={codexLoading}
            importingId={importingId}
            onLoad={() => loadCodex(codexCwd)}
            onImport={handleImportCodex}
          />
        )}

        {/* Footer */}
        <div className="flex justify-end gap-2 pt-1">
          <Button variant="ghost" onClick={onClose} disabled={!!importingId}>
            Cancel
          </Button>
        </div>
      </div>
    </Modal>
  );
}

// ──────────────────────────────────────────
// CBC Section
// ──────────────────────────────────────────

interface CbcSectionProps {
  projectsLoading: boolean;
  drives: string[];
  selectedDrive: string | null;
  onDriveChange: (drive: string | null) => void;
  driveSessionCount: (drive: string) => number;
  filteredProjects: CbcProject[];
  selectedProject: string | null;
  onProjectChange: (dir: string) => void;
  cbcSessions: CbcSessionItem[];
  cbcLoading: boolean;
  importingId: string | null;
  onImport: (item: CbcSessionItem) => void;
}

function CbcSection({
  projectsLoading,
  drives,
  selectedDrive,
  onDriveChange,
  driveSessionCount,
  filteredProjects,
  selectedProject,
  onProjectChange,
  cbcSessions,
  cbcLoading,
  importingId,
  onImport,
}: CbcSectionProps) {
  // Front-end path filter: narrow the session list by the session's
  // project_dir (cbc sessions are scoped to a project, so this is the path).
  const [pathFilter, setPathFilter] = useState('');
  const pathFilterTrim = pathFilter.trim();
  const visibleSessions = pathFilterTrim
    ? cbcSessions.filter((s) =>
        s.project_dir.toLowerCase().includes(pathFilterTrim.toLowerCase()),
      )
    : cbcSessions;

  return (
    <>
      {/* Loading */}
      {projectsLoading && (
        <div className="py-4 text-center text-sm text-text-tertiary">
          Loading projects...
        </div>
      )}

      {/* Empty projects */}
      {!projectsLoading && drives.length === 0 && (
        <div className="py-4 text-center text-sm text-text-tertiary">
          No projects found
        </div>
      )}

      {/* Drive select */}
      {!projectsLoading && drives.length > 0 && (
        <label className="flex flex-col gap-1">
          <span className="text-xs font-medium text-text-secondary">Drive</span>
          <select
            value={selectedDrive ?? ''}
            onChange={(e) =>
              onDriveChange(e.target.value || null)
            }
            className="rounded border border-border-muted bg-bg-primary px-3 py-1.5 text-sm text-text-primary outline-none focus:border-accent"
          >
            <option value="">All drives</option>
            {drives.map((d) => (
              <option key={d} value={d}>
                {d} ({driveSessionCount(d)})
              </option>
            ))}
          </select>
        </label>
      )}

      {/* Project select */}
      {!projectsLoading && drives.length > 0 && (
        <label className="flex flex-col gap-1">
          <span className="text-xs font-medium text-text-secondary">
            Project
          </span>
          <select
            value={selectedProject ?? ''}
            onChange={(e) => onProjectChange(e.target.value)}
            className="rounded border border-border-muted bg-bg-primary px-3 py-1.5 text-sm text-text-primary outline-none focus:border-accent"
          >
            <option value="">Select a project</option>
            {filteredProjects.map((p) => (
              <option key={p.project_dir} value={p.project_dir}>
                {p.short_label}{' '}
                {p.session_count > 0 && `(${p.session_count})`}
                {p.resumable_count !== undefined &&
                  p.resumable_count > 0 &&
                  ` — ${p.resumable_count} resumable`}
              </option>
            ))}
          </select>
        </label>
      )}

      {/* No project selected hint */}
      {!projectsLoading &&
        drives.length > 0 &&
        !selectedProject && (
          <div className="py-2 text-center text-sm text-text-tertiary">
            Select a project
          </div>
        )}

      {/* Loading sessions */}
      {selectedProject && cbcLoading && (
        <div className="py-4 text-center text-sm text-text-tertiary">
          Loading...
        </div>
      )}

      {/* Empty sessions */}
      {selectedProject &&
        !cbcLoading &&
        cbcSessions.length === 0 && (
          <div className="py-2 text-center text-sm text-text-tertiary">
            No sessions in this project
          </div>
        )}

      {/* Front-end path filter */}
      {selectedProject && !cbcLoading && cbcSessions.length > 0 && (
        <input
          type="text"
          value={pathFilter}
          onChange={(e) => setPathFilter(e.target.value)}
          placeholder="Filter by path (project_dir)…"
          className="rounded border border-border-muted bg-bg-primary px-3 py-1.5 text-sm text-text-primary outline-none placeholder:text-text-tertiary focus:border-accent"
        />
      )}

      {/* No sessions match the path filter */}
      {selectedProject &&
        !cbcLoading &&
        cbcSessions.length > 0 &&
        visibleSessions.length === 0 && (
          <div className="py-2 text-center text-sm text-text-tertiary">
            No sessions match “{pathFilterTrim}”
          </div>
        )}

      {/* Session list */}
      {selectedProject &&
        !cbcLoading &&
        visibleSessions.length > 0 && (
          <div className="max-h-64 overflow-y-auto space-y-1 rounded border border-border-muted bg-bg-primary p-1">
            {visibleSessions.map((item) => (
              <CbcSessionItemRow
                key={item.session_id}
                item={item}
                isImporting={importingId === item.session_id}
                onClick={() => onImport(item)}
              />
            ))}
          </div>
        )}
    </>
  );
}

// ──────────────────────────────────────────
// CBC Session Item
// ──────────────────────────────────────────

function CbcSessionItemRow({
  item,
  isImporting,
  onClick,
}: {
  item: CbcSessionItem;
  isImporting: boolean;
  onClick: () => void;
}) {
  const ts = item.last_timestamp || item.first_timestamp || '';
  const isFork = !!item.forked_from;

  return (
    <div
      onClick={onClick}
      className={`rounded px-2.5 py-2 cursor-pointer transition-colors hover:bg-bg-tertiary ${
        isImporting ? 'opacity-50 pointer-events-none' : ''
      }`}
      title={
        isFork
          ? `Forked from: ${item.forked_from}`
          : undefined
      }
    >
      <div className="flex items-center gap-1.5">
        <span className="text-sm text-text-primary truncate">
          {item.title}
        </span>
        {isFork && (
          <span className="shrink-0 rounded bg-warning/20 px-1 text-[10px] font-medium text-warning">
            fork
          </span>
        )}
      </div>
      <div className="text-xs text-text-tertiary mt-0.5">
        {item.message_count} msgs &middot; {item.model} &middot;{' '}
        {ts ? formatTime(ts) : '—'}
      </div>
    </div>
  );
}

